json_schema:
{
  "$id": "https://json.schemastore.org/drupal-links-task.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": {
    "type": "object",
    "properties": {
      "title": {
        "title": "The static title for the local task",
        "type": "string"
      },
      "title_context": {
        "title": "The translation context for the title value.",
        "type": "string"
      },
      "route_name": {
        "title": "The name of the route this task links to",
        "type": "string"
      },
      "route_parameters": {
        "title": "Parameters for route variables when generating a link",
        "type": "object"
      },
      "base_route": {
        "title": "The route name where the root tab appears",
        "type": "string"
      },
      "parent_id": {
        "title": "The plugin ID of the parent tab",
        "type": "string"
      },
      "weight": {
        "title": "The weight of the tab",
        "type": "integer"
      },
      "options": {
        "title": "Array of link options",
        "type": "object"
      },
      "class": {
        "title": "Class for task implementations",
        "type": "string"
      },
      "deriver": {
        "title": "Deriver class",
        "type": "string"
      },
      "cache_tags": {
        "title": "Cache tags",
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    },
    "additionalProperties": false
  },
  "title": "JSON schema for Drupal task links file",
  "type": "object"
}

{
  "$comment": "https://minecraft.fandom.com/wiki/Item_modifier#JSON_structure",
  "$id": "https://json.schemastore.org/minecraft-item-modifier.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "slotEnum": {
      "enum": ["mainhand", "offhand", "feet", "legs", "chest", "head"]
    },
    "numberProvider": {
      "$comment": "https://minecraft.fandom.com/wiki/Loot_table#Number_Providers",
      "properties": {
        "type": {
          "title": "Type",
          "description": "The number provider type.",
          "type": "string",
          "enum": [
            "minecraft:constant",
            "minecraft:uniform",
            "minecraft:binomial",
            "minecraft:score"
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:constant"
              }
            }
          },
          "then": {
            "description": "A constant value.",
            "properties": {
              "value": {
                "title": "Value",
                "description": "The exact value.",
                "type": "number"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:uniform"
              }
            }
          },
          "then": {
            "description": "A random number following a uniform distribution between two values (inclusive).",
            "properties": {
              "min": {
                "title": "Minimum",
                "description": "The minimum value.",
                "type": ["number", "object"],
                "$ref": "#/definitions/numberProvider"
              },
              "max": {
                "title": "Max",
                "description": "The maximum value.",
                "type": ["number", "object"],
                "$ref": "#/definitions/numberProvider"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:binomial"
              }
            }
          },
          "then": {
            "description": "A random number following a binomial distribution.",
            "properties": {
              "n": {
                "title": "n",
                "description": "The amount of trials.",
                "type": ["integer", "object"],
                "$ref": "#/definitions/numberProvider"
              },
              "p": {
                "title": "p",
                "description": "The probability of success on an individual trial.",
                "$ref": "#/definitions/numberProvider"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:score"
              }
            }
          },
          "then": {
            "description": "A scoreboard value.",
            "properties": {
              "target": {
                "title": "Target",
                "description": "Scoreboard name provider.",
                "type": ["string", "object"],
                "enum": ["this", "killer", "direct_killer", "player_killer"],
                "properties": {
                  "type": {
                    "title": "Type",
                    "description": "Resource location.",
                    "type": "string",
                    "enum": ["fixed", "context"]
                  }
                },
                "allOf": [
                  {
                    "if": {
                      "properties": {
                        "type": {
                          "const": "fixed"
                        }
                      }
                    },
                    "then": {
                      "properties": {
                        "name": {
                          "title": "Name",
                          "description": "A UUID or player name.",
                          "type": "string"
                        }
                      }
                    }
                  },
                  {
                    "if": {
                      "properties": {
                        "type": {
                          "const": "context"
                        }
                      }
                    },
                    "then": {
                      "properties": {
                        "target": {
                          "title": "Target",
                          "type": "string",
                          "enum": [
                            "this",
                            "killer",
                            "direct_killer",
                            "player_killer"
                          ]
                        }
                      }
                    }
                  }
                ]
              },
              "score": {
                "title": "Score",
                "description": "The scoreboard objective.",
                "type": "string"
              },
              "scale": {
                "title": "Scale",
                "description": "Scale to multiply the score before returning it.",
                "type": "number"
              }
            }
          }
        }
      ]
    }
  },
  "description": "Configuration file defining an item modifier for a data pack for Minecraft.",
  "items": {
    "properties": {
      "function": {
        "title": "Function",
        "description": "Namespaced ID of the function to apply.",
        "type": "string",
        "enum": [
          "minecraft:apply_bonus",
          "minecraft:copy_name",
          "minecraft:copy_nbt",
          "minecraft:copy_state",
          "minecraft:enchant_randomly",
          "minecraft:enchant_with_levels",
          "minecraft:exploration_map",
          "minecraft:explosion_decay",
          "minecraft:furnace_smelt",
          "minecraft:fill_player_head",
          "minecraft:limit_count",
          "minecraft:looting_enchant",
          "minecraft:set_attributes",
          "minecraft:set_banner_pattern",
          "minecraft:set_contents",
          "minecraft:set_count",
          "minecraft:set_damage",
          "minecraft:set_enchantments",
          "minecraft:set_loot_table",
          "minecraft:set_lore",
          "minecraft:set_name",
          "minecraft:set_nbt",
          "minecraft:set_stew_effect"
        ]
      }
    },
    "allOf": [
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:apply_bonus"
            }
          }
        },
        "then": {
          "description": "Applies a predefined bonus formula.",
          "type": "object",
          "properties": {
            "enchantment": {
              "title": "Enchantment",
              "description": "Enchantment ID used for level calculation.",
              "type": "string"
            },
            "formula": {
              "title": "Forumla",
              "type": "string",
              "enum": [
                "binomial_with_bonus_count",
                "uniform_bonus_count",
                "ore_drops"
              ]
            },
            "parameters": {
              "title": "Parameters",
              "description": "Values required for the formula.",
              "type": "object",
              "properties": {
                "extra": {
                  "title": "Extra",
                  "description": "For formula 'binomial_with_bonus_count', the extra value.",
                  "type": "integer"
                },
                "probability": {
                  "title": "Probability",
                  "description": "For formula 'binomial_with_bonus_count', the probability.",
                  "type": "number"
                },
                "bonusMultiplier": {
                  "title": "Bonus Multiplier",
                  "description": "For formula 'uniform_bonus_count', the bonus multiplier.",
                  "type": "number"
                }
              }
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:copy_name"
            }
          }
        },
        "then": {
          "description": "For loot table type 'block', copies a block entity's CustomName tag into the item's display.",
          "type": "object",
          "properties": {
            "source": {
              "title": "Source",
              "type": "string",
              "enum": ["block_entity"],
              "default": "block_entity"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:copy_nbt"
            }
          }
        },
        "then": {
          "description": "Copies NBT to the item.",
          "type": "object",
          "properties": {
            "source": {
              "title": "Source",
              "anyOf": [
                {
                  "type": "string",
                  "enum": ["block_entity", "this", "killer", "killer_player"]
                },
                {
                  "type": "string"
                },
                {
                  "type": "object",
                  "properties": {
                    "type": {
                      "title": "Type",
                      "description": "NBT provider type.",
                      "type": "string",
                      "enum": ["minecraft:context", "minecraft:storage"]
                    }
                  },
                  "allOf": [
                    {
                      "if": {
                        "properties": {
                          "type": {
                            "const": "minecraft:context"
                          }
                        }
                      },
                      "then": {
                        "properties": {
                          "target": {
                            "title": "Target",
                            "description": "Same as source above.",
                            "type": "string"
                          }
                        }
                      }
                    },
                    {
                      "if": {
                        "properties": {
                          "type": {
                            "const": "minecraft:storage"
                          }
                        }
                      },
                      "then": {
                        "properties": {
                          "target": {
                            "title": "Source",
                            "description": "A resource location specifying the storage ID.",
                            "type": "string"
                          }
                        }
                      }
                    }
                  ]
                }
              ]
            },
            "ops": {
              "title": "Operations",
              "description": "A list of copy operations.",
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "source": {
                    "title": "Source",
                    "description": "The NBT path to copy from.",
                    "type": "string"
                  },
                  "target": {
                    "title": "Target",
                    "description": "The NBT path to copy to, starting from the item's tag tag.",
                    "type": "string"
                  },
                  "op": {
                    "title": "Operation",
                    "description": "Can be replace to replace any existing contents of the target, append to append to a list, or merge to merge into a compound tag.",
                    "type": "string"
                  }
                }
              }
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:copy_state"
            }
          }
        },
        "then": {
          "description": "Copies state properties from dropped block to the item's BlockStateTag tag.",
          "properties": {
            "block": {
              "title": "Block",
              "description": "A block ID. Function fails if the block doesn't match.",
              "type": "string"
            },
            "properties": {
              "title": "Properties",
              "description": "A list of property names to copy.",
              "type": "array",
              "items": {
                "title": "Property",
                "description": "A block state name to copy.",
                "type": "string"
              }
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:enchant_randomly"
            }
          }
        },
        "then": {
          "description": "Enchants the item with one randomly-selected enchantment. The level of the enchantment, if applicable, is random.",
          "properties": {
            "enchantments": {
              "title": "Enchantments",
              "description": "List of enchantment IDs to choose from.",
              "type": "array"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:enchant_with_levels"
            }
          }
        },
        "then": {
          "description": "Enchants the item, with the specified enchantment level (roughly equivalent to using an enchantment table at that level).",
          "properties": {
            "treasure": {
              "title": "Treasure",
              "description": "Determines whether treasure enchantments are allowed on this item.",
              "type": "boolean"
            },
            "levels": {
              "title": "Levels",
              "description": "Specifies the exact enchantment level to use.",
              "type": ["integer", "object"],
              "$ref": "#/definitions/numberProvider"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:exploration_map"
            }
          }
        },
        "then": {
          "description": "Converts an empty map into an explorer map leading to a nearby generated structure.",
          "properties": {
            "destination": {
              "title": "Destination",
              "description": "The type of generated structure to locate. Accepts any of the StructureTypes used by the /locate command (case insensitive).",
              "type": "string"
            },
            "decoration": {
              "title": "Decoration",
              "description": "The icon used to mark the destination on the map. Accepts any of the map icon text IDs (case insensitive).",
              "type": "string"
            },
            "zoom": {
              "title": "Zoom",
              "description": "The zoom level of the resulting map.",
              "type": "integer",
              "default": 2
            },
            "search_radius": {
              "title": "Search Radius",
              "description": "The size, in chunks, of the area to search for structures. The area checked is square, not circular.",
              "type": "integer",
              "default": 50
            },
            "skip_existing_chunks": {
              "title": "Skip Existing Chunks",
              "description": "Don't search in chunks that have already been generated.",
              "type": "boolean",
              "default": true
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:explosion_decay"
            }
          }
        },
        "then": {
          "description": "For loot tables of type 'block', removes some items from a stack, if there was an explosion. Each item has a chance of 1/explosion radius to be lost."
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:furnace_smelt"
            }
          }
        },
        "then": {
          "description": "Smelts the item as it would be in a furnace. Used in combination with the entity_properties condition to cook food from animals on death."
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:fill_player_head"
            }
          }
        },
        "then": {
          "description": "Adds required item tags of a player head.",
          "properties": {
            "entity": {
              "title": "Entity",
              "description": "Specifies an entity to be used for the player head.",
              "type": "string"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:limit_count"
            }
          }
        },
        "then": {
          "description": "Limits the count of every item stack.",
          "properties": {
            "limit": {
              "title": "Limit",
              "description": "Specifies the exact limit to use.",
              "type": ["integer", "object"],
              "$ref": "#/definitions/numberProvider",
              "properties": {
                "min": {
                  "title": "Minimum",
                  "description": "Minimum limit to use.",
                  "type": ["integer", "object"],
                  "$ref": "#/definitions/numberProvider"
                },
                "max": {
                  "title": "Max",
                  "description": "Max limit to use.",
                  "type": ["integer", "object"],
                  "$ref": "#/definitions/numberProvider"
                }
              }
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:looting_enchant"
            }
          }
        },
        "then": {
          "description": "Adjusts the stack size based on the level of the Looting enchantment on the killer entity.",
          "properties": {
            "count": {
              "title": "Count",
              "description": "Specifies the number of additional items per level of looting.",
              "type": ["integer", "object"],
              "$ref": "#/definitions/numberProvider"
            },
            "limit": {
              "title": "Limit",
              "description": "Specifies the maximum amount of items in the stack after the looting calculation. If the value is 0, no limit is applied.",
              "type": "integer"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_attributes"
            }
          }
        },
        "then": {
          "description": "Add attribute modifiers to the item.",
          "properties": {
            "modifiers": {
              "title": "Modifiers",
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": {
                  "properties": {
                    "name": {
                      "title": "Name",
                      "description": "Name of the modifer.",
                      "type": "string"
                    },
                    "attribute": {
                      "title": "Attribute",
                      "description": "The name of the attribute this modifer is to act upon.",
                      "type": "string"
                    },
                    "operation": {
                      "title": "Operation",
                      "type": "string",
                      "enum": ["addition", "multiply_base", "multiply_total"]
                    },
                    "amount": {
                      "title": "Amount",
                      "description": "Specifies the amount of the modifier.",
                      "type": ["number", "object"],
                      "$ref": "#/definitions/numberProvider"
                    },
                    "id": {
                      "title": "ID",
                      "description": "UUID of the modifier following.",
                      "type": "string"
                    },
                    "slot": {
                      "title": "Slot",
                      "description": "Slots the item must be in for the modifier to take effect.",
                      "type": ["string", "array"],
                      "$ref": "#/definitions/slotEnum",
                      "items": {
                        "type": "string",
                        "$ref": "#/definitions/slotEnum"
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_banner_pattern"
            }
          }
        },
        "then": {
          "description": "Sets tags needed for banner patterns.",
          "properties": {
            "patterns": {
              "title": "Patterns",
              "description": "List of patterns.",
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": {
                  "type": "object",
                  "properties": {
                    "pattern": {
                      "title": "Pattern",
                      "description": "The pattern type.",
                      "type": "string"
                    },
                    "color": {
                      "title": "Color",
                      "description": "The color for this pattern.",
                      "type": "string",
                      "enum": [
                        "white",
                        "orange",
                        "magenta",
                        "light_blue",
                        "yellow",
                        "lime",
                        "pink",
                        "gray",
                        "light_gray",
                        "cyan",
                        "purple",
                        "blue",
                        "brown",
                        "green",
                        "red",
                        "black"
                      ]
                    }
                  }
                }
              }
            },
            "append": {
              "title": "Append",
              "description": "If true, new patterns will be appended to existing ones.",
              "type": "boolean"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_contents"
            }
          }
        },
        "then": {
          "description": "For loot tables of type 'block', sets the contents of a container block item to a list of entries.",
          "properties": {
            "entries": {
              "title": "Entries",
              "description": "The entries to use as contents.",
              "type": "array"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_count"
            }
          }
        },
        "then": {
          "description": "Sets the stack size.",
          "properties": {
            "count": {
              "title": "Count",
              "description": "Specifies the stack size to set.",
              "type": ["integer", "object"],
              "$ref": "#/definitions/numberProvider"
            },
            "add": {
              "title": "Add",
              "description": "If true, change will be relative to the current count.",
              "type": "boolean"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_damage"
            }
          }
        },
        "then": {
          "description": "Sets the item's damage value (durability) for tools.",
          "properties": {
            "damage": {
              "title": "Damage",
              "description": "Specifies the damage fraction to set (1.0 is undamaged, 0.0 is zero durability left).",
              "type": ["number", "object"],
              "$ref": "#/definitions/numberProvider"
            },
            "add": {
              "title": "Add",
              "description": "If true, change will be relative to current damage.",
              "type": "boolean"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_enchantments"
            }
          }
        },
        "then": {
          "description": "Sets the item's enchantments.",
          "properties": {
            "enchantments": {
              "title": "Enchantments",
              "description": "Enchantments to add.",
              "type": "object",
              "additionalProperties": {
                "description": "Key name is the enchantment ID.",
                "type": ["integer", "object"],
                "$ref": "#/definitions/numberProvider"
              }
            },
            "add": {
              "title": "Add",
              "description": "If true, change will be relative to current level.",
              "type": "boolean"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_loot_table"
            }
          }
        },
        "then": {
          "description": "Sets the loot table for a container (chest etc.).",
          "properties": {
            "name": {
              "title": "Name",
              "description": "Specifies the resource location of the loot table to be used.",
              "type": "string"
            },
            "seed": {
              "title": "Seed",
              "description": "Specifies the loot table seed. If absent or set to 0, a random seed will be used.",
              "type": "integer"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_lore"
            }
          }
        },
        "then": {
          "description": "Adds lore to the item.",
          "properties": {
            "lore": {
              "title": "Lore",
              "description": "List of JSON text components. Each list entry represents one line of the lore. Advanced components are resolved only if entity successfully targets an entity.",
              "type": "array",
              "items": {
                "type": "object"
              }
            },
            "entity": {
              "title": "Entity",
              "description": "Specifies the entity to act as the source @s in the JSON text component.",
              "type": "string"
            },
            "replace": {
              "title": "Replace",
              "description": "If true, replaces all existing lines of lore, if false appends the list.",
              "type": "boolean"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_name"
            }
          }
        },
        "then": {
          "description": "Adds display name of the item.",
          "properties": {
            "name": {
              "title": "Name",
              "description": "A JSON text component name, allowing color, translations, etc. Advanced components are resolved only if entity successfully targets an entity.",
              "type": ["array", "object", "string"]
            },
            "entity": {
              "title": "Entity",
              "description": "Specifies an entity to act as source @s in the JSON text component.",
              "type": "string"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_nbt"
            }
          }
        },
        "then": {
          "description": "Adds NBT data to the item.",
          "properties": {
            "tag": {
              "title": "Tag",
              "description": "Tag string to add, similar to those used by commands. Note that the first bracket is required and quotation marks need to be escaped using a backslash (\\).",
              "type": "string"
            }
          }
        }
      },
      {
        "if": {
          "properties": {
            "function": {
              "const": "minecraft:set_stew_effect"
            }
          }
        },
        "then": {
          "description": "Sets the status effects for suspicious stew.",
          "properties": {
            "effects": {
              "title": "Effects",
              "description": "The effects to apply.",
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": {
                  "type": "object",
                  "properties": {
                    "type": {
                      "title": "Type",
                      "description": "The effect ID.",
                      "type": "string"
                    },
                    "duration": {
                      "title": "Duration",
                      "description": "The duration of the effect.",
                      "type": ["integer", "object"],
                      "$ref": "#/definitions/numberProvider"
                    }
                  }
                }
              }
            }
          }
        }
      }
    ]
  },
  "title": "Minecraft Data Pack Item Modifier",
  "type": "array"
}

{
  "$defs": {},
  "$id": "https://json.schemastore.org/clang-format.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": {},
  "description": "The .clang-format file is a YAML file defining formatting styles used by clang-format.\r\r see https://clang.llvm.org/docs/ClangFormatStyleOptions.html",
  "patternProperties": {
    "^x-": {
      "$comment": "yaml marker for multiple documents in one single yaml file"
    }
  },
  "properties": {
    "BasedOnStyle": {
      "$comment": "clang-format ignores cases. For the sake of consistency, use one of following enums",
      "description": "The style used for all options not specifically set in the configuration.",
      "type": "string",
      "enum": [
        "Chromium",
        "Google",
        "LLVM",
        "Mozilla",
        "WebKit",
        "Microsoft",
        "GNU",
        "InheritParentConfig",
        "chromium",
        "google",
        "llvm",
        "mozilla",
        "webkit",
        "microsoft",
        "gnu",
        "inheritparentconfig"
      ]
    },
    "AccessModifierOffset": {
      "description": "clang-format 3.3\r\r The extra indent or outdent of access modifiers, e.g. public:.",
      "type": "integer"
    },
    "AlignAfterOpenBracket": {
      "description": "clang-format 3.8\r\r This applies to round brackets (parentheses), angle brackets and square brackets.",
      "type": "string",
      "enum": ["Align", "DontAlign", "AlwaysBreak", "BlockIndent"]
    },
    "AlignArrayOfStructures": {
      "description": "clang-format 13\r\r if not None, when using initialization for an array of structs aligns the fields into columns.\r\r NOTE: In clang-format 15 this option only applied to arrays with equal number of columns per row.",
      "type": "string",
      "enum": ["None", "Left", "Right"]
    },
    "AlignConsecutiveMacros": {
      "oneOf": [
        {
          "description": "clang-format 9\r\r Style of aligning consecutive macros.",
          "type": "string",
          "enum": [
            "None",
            "Consecutive",
            "AcrossEmptyLines",
            "AcrossComments",
            "AcrossEmptyLinesAndComments"
          ]
        },
        {
          "description": "clang-format 15\r\r Alignment options.",
          "type": "object",
          "properties": {
            "Enabled": {
              "description": "Whether aligning is enabled.",
              "type": "boolean"
            },
            "AcrossEmptyLines": {
              "description": "Whether to align across empty lines.",
              "type": "boolean"
            },
            "AcrossComments": {
              "description": "Whether to align across comments.",
              "type": "boolean"
            }
          }
        }
      ]
    },
    "AlignConsecutiveAssignments": {
      "oneOf": [
        {
          "description": "clang-format 3.8\r\r Style of aligning consecutive assignments.",
          "type": "string",
          "enum": [
            "None",
            "Consecutive",
            "AcrossEmptyLines",
            "AcrossComments",
            "AcrossEmptyLinesAndComments"
          ]
        },
        {
          "description": "clang-format 15\r\r Alignment options.",
          "type": "object",
          "properties": {
            "Enabled": {
              "description": "Whether aligning is enabled.",
              "type": "boolean"
            },
            "AcrossEmptyLines": {
              "description": "Whether to align across empty lines.",
              "type": "boolean"
            },
            "AcrossComments": {
              "description": "Whether to align across comments.",
              "type": "boolean"
            },
            "AlignCompound": {
              "description": "Whether compound assignments like += are aligned along with =.",
              "type": "boolean"
            },
            "PadOperators": {
              "description": "Whether short assignment operators are left-padded to the same length as long ones in order to put all assignment operators to the right of the left hand side.",
              "type": "boolean"
            }
          }
        }
      ]
    },
    "AlignConsecutiveBitFields": {
      "oneOf": [
        {
          "description": "clang-format 11\r\r Style of aligning consecutive bit fields.",
          "type": "string",
          "enum": [
            "None",
            "Consecutive",
            "AcrossEmptyLines",
            "AcrossComments",
            "AcrossEmptyLinesAndComments"
          ]
        },
        {
          "description": "clang-format 15\r\r Alignment options.",
          "type": "object",
          "properties": {
            "Enabled": {
              "description": "Whether aligning is enabled.",
              "type": "boolean"
            },
            "AcrossEmptyLines": {
              "description": "Whether to align across empty lines.",
              "type": "boolean"
            },
            "AcrossComments": {
              "description": "Whether to align across comments.",
              "type": "boolean"
            }
          }
        }
      ]
    },
    "AlignConsecutiveDeclarations": {
      "oneOf": [
        {
          "description": "clang-format 3.8\r\r Style of aligning consecutive declarations.",
          "type": "string",
          "enum": [
            "None",
            "Consecutive",
            "AcrossEmptyLines",
            "AcrossComments",
            "AcrossEmptyLinesAndComments"
          ]
        },
        {
          "description": "clang-format 15\r\r Alignment options.",
          "type": "object",
          "properties": {
            "Enabled": {
              "description": "Whether aligning is enabled.",
              "type": "boolean"
            },
            "AcrossEmptyLines": {
              "description": "Whether to align across empty lines.",
              "type": "boolean"
            },
            "AcrossComments": {
              "description": "Whether to align across comments.",
              "type": "boolean"
            }
          }
        }
      ]
    },
    "AlignEscapedNewlines": {
      "description": "clang-format 5\r\r Options for aligning backslashes in escaped newlines.",
      "type": "string",
      "enum": ["Left", "Right", "DontAlign"]
    },
    "AlignOperands": {
      "description": "clang-format 3.5\r\r If true, horizontally align operands of binary and ternary expressions.",
      "type": "string",
      "enum": ["Align", "DontAlign", "AlignAfterOperator"]
    },
    "AlignTrailingComments": {
      "oneOf": [
        {
          "description": "clang-format 3.7\r\r Control of trailing comments.\r\r NOTE: In clang-format 16 this option is not a bool but can be set to the options. Conventional bool options still can be parsed as before.",
          "type": "boolean"
        },
        {
          "description": "clang-format 16\r\r Alignment options.",
          "type": "object",
          "properties": {
            "Kind": {
              "description": "Specifies the way to align trailing comments.",
              "type": "string",
              "enum": ["Leave", "Always", "Never"]
            },
            "OverEmptyLines": {
              "description": "How many empty lines to apply alignment.",
              "type": "integer",
              "minimum": 0
            }
          }
        }
      ]
    },
    "AllowAllArgumentsOnNextLine": {
      "description": "clang-format 9\r\r If a function call or braced initializer list doesn't fit on a line, allow putting all arguments onto the next line, even if BinPackArguments is false.",
      "type": "boolean"
    },
    "AllowAllConstructorInitializersOnNextLine": {
      "description": "clang-format 9\r\r This option is deprecated in clang-format 15. See NextLine of PackConstructorInitializers.\r\r If a constructor definition with a member initializer list doesn't fit on a single line, allow putting all member initializers onto the next line, if `ConstructorInitializerAllOnOneLineOrOnePerLine` is true. Note that this parameter has no effect if `ConstructorInitializerAllOnOneLineOrOnePerLine` is false.",
      "type": "boolean"
    },
    "AllowAllParametersOfDeclarationOnNextLine": {
      "description": "clang-format 3.3\r\r If the function declaration doesn't fit on a line, allow putting all parameters of a function declaration onto the next line even if BinPackParameters is false.",
      "type": "boolean"
    },
    "AllowShortEnumsOnASingleLine": {
      "description": "clang-format 11\r\r Allow short enums on a single line.",
      "type": "boolean"
    },
    "AllowShortBlocksOnASingleLine": {
      "description": "clang-format 3.5\r\r Dependent on the value, while (true) { continue; } can be put on a single line.",
      "type": "string",
      "enum": ["Never", "Empty", "Always"]
    },
    "AllowShortCaseLabelsOnASingleLine": {
      "description": "clang-format 3.6\r\r If true, short case labels will be contracted to a single line.",
      "type": "boolean"
    },
    "AllowShortFunctionsOnASingleLine": {
      "description": "clang-format 3.5\r\r Dependent on the value, int f() { return 0; } can be put on a single line.",
      "type": "string",
      "enum": ["All", "None", "Inline", "Empty", "InlineOnly"]
    },
    "AllowShortLambdasOnASingleLine": {
      "description": "clang-format 9\r\r Dependent on the value, auto lambda []() { return 0; } can be put on a single line.",
      "type": "string",
      "enum": ["None", "Empty", "Inline", "All"]
    },
    "AllowShortIfStatementsOnASingleLine": {
      "description": "clang-format 9\r\r If true, if (a) return; can be put on a single line.",
      "type": "string",
      "enum": ["AllIfsAndElse", "Never", "WithoutElse", "OnlyFirstIf"]
    },
    "AllowShortLoopsOnASingleLine": {
      "description": "clang-format 3.7\r\r If true, while (true) continue; can be put on a single line.",
      "type": "boolean"
    },
    "AlwaysBreakAfterDefinitionReturnType": {
      "description": "clang-format 3.7\r\r This option is deprecated and is retained for backwards compatibility.\r\r The function definition return type breaking style to use. This option is deprecated and is retained for backwards compatibility",
      "type": "string",
      "enum": ["None", "All", "TopLevel"]
    },
    "AlwaysBreakAfterReturnType": {
      "description": "clang-format 3.8\r\r The function declaration return type breaking style to use.",
      "type": "string",
      "enum": [
        "None",
        "All",
        "TopLevel",
        "AllDefinitions",
        "TopLevelDefinitions"
      ]
    },
    "AlwaysBreakBeforeMultilineStrings": {
      "description": "clang-format 3.4\r\r If true, always break before multiline string literals.",
      "type": "boolean"
    },
    "AlwaysBreakTemplateDeclarations": {
      "description": "clang-format 7\r\r The template declaration breaking style to use.",
      "type": "string",
      "enum": ["Yes", "No", "MultiLine"]
    },
    "AttributeMacros": {
      "description": "clang-format 12\r\r A vector of strings that should be interpreted as attributes/qualifiers instead of identifiers. This can be useful for language extensions or static analyzer annotations.",
      "type": "array",
      "items": {
        "type": "string",
        "examples": ["__capability", "__output", "__ununsed"]
      }
    },
    "BinPackArguments": {
      "description": "clang-format 3.7\r\r If false, a function call's arguments will either be all on the same line or will have one line each.",
      "type": "boolean"
    },
    "BinPackParameters": {
      "description": "clang-format 3.7\r\r If false, a function declaration's or function definition's parameters will either all be on the same line or will have one line each.",
      "type": "boolean"
    },
    "BitFieldColonSpacing": {
      "description": "clang-format 12\r\r The BitFieldColonSpacingStyle to use for bitfields.",
      "type": "string",
      "enum": ["Both", "None", "Before", "After"]
    },
    "BraceWrapping": {
      "description": "clang-format 3.8\r\r Control of individual brace wrapping cases.If BreakBeforeBraces is set to BS_Custom, use this to specify how each individual brace case should be handled. Otherwise, this is ignored.",
      "type": "object",
      "properties": {
        "AfterCaseLabel": {
          "description": "Wrap case labels.",
          "type": "boolean"
        },
        "AfterClass": {
          "description": "Wrap class definitions.",
          "type": "boolean"
        },
        "AfterControlStatement": {
          "description": "Wrap control statements (if/for/while/switch/...).",
          "type": "string",
          "enum": ["Never", "MultiLine", "Always"]
        },
        "AfterEnum": {
          "description": "Wrap enum definitions.",
          "type": "boolean"
        },
        "AfterFunction": {
          "description": "Wrap function definitions.",
          "type": "boolean"
        },
        "AfterNamespace": {
          "description": "Wrap namespace definitions.",
          "type": "boolean"
        },
        "AfterObjCDeclaration": {
          "description": "Wrap ObjC definitions (interfaces, implementations…). @autoreleasepool and @synchronized blocks are wrapped according to AfterControlStatement flag.",
          "type": "boolean"
        },
        "AfterStruct": {
          "description": "Wrap struct definitions.",
          "type": "boolean"
        },
        "AfterUnion": {
          "description": "Wrap union definitions.",
          "type": "boolean"
        },
        "AfterExternBlock": {
          "description": "Wrap extern blocks.",
          "type": "boolean"
        },
        "BeforeCatch": {
          "description": "Wrap before catch.",
          "type": "boolean"
        },
        "BeforeElse": {
          "description": "Wrap before else.",
          "type": "boolean"
        },
        "BeforeLambdaBody": {
          "description": "Wrap lambda block.",
          "type": "boolean"
        },
        "BeforeWhile": {
          "description": "Wrap before while.",
          "type": "boolean"
        },
        "IndentBraces": {
          "description": "Indent the wrapped braces themselves.",
          "type": "boolean"
        },
        "SplitEmptyFunction": {
          "description": "If false, empty function body can be put on a single line. This option is used only if the opening brace of the function has already been wrapped, i.e. the AfterFunction brace wrapping mode is set, and the function could/should not be put on a single line (as per AllowShortFunctionsOnASingleLine and constructor formatting options).",
          "type": "boolean"
        },
        "SplitEmptyRecord": {
          "description": "If false, empty record (e.g. class, struct or union) body can be put on a single line. This option is used only if the opening brace of the record has already been wrapped, i.e. the AfterClass (for classes) brace wrapping mode is set.",
          "type": "boolean"
        },
        "SplitEmptyNamespace": {
          "description": "If false, empty namespace body can be put on a single line. This option is used only if the opening brace of the namespace has already been wrapped, i.e. the AfterNamespace brace wrapping mode is set.",
          "type": "boolean"
        }
      }
    },
    "BreakAfterAttributes": {
      "description": "clang-format 16\r\r Break after a group of C++11 attributes before a function declaration/definition name.",
      "type": "string",
      "enum": ["Always", "Leave", "Never"]
    },
    "BreakAfterJavaFieldAnnotations": {
      "description": "clang-format 3.8\r\r Break after each annotation on a field in Java files.",
      "type": "boolean"
    },
    "BreakArrays": {
      "description": "clang-format 16\r\r If true, clang-format will always break after a Json array [ otherwise it will scan until the closing ] to determine if it should add newlines between elements (prettier compatible).",
      "type": "boolean"
    },
    "BreakBeforeInlineASMColon": {
      "description": "clang-format 16\r\r The inline ASM colon style to use..",
      "type": "string",
      "enum": ["Never", "OnlyMultiline", "Always"]
    },
    "BreakBeforeBinaryOperators": {
      "description": "clang-format 3.6\r\r The way to wrap binary operators.",
      "type": "string",
      "enum": ["None", "NonAssignment", "All"]
    },
    "BreakBeforeBraces": {
      "description": "clang-format 3.7\r\r The brace breaking style to use.",
      "type": "string",
      "enum": [
        "Attach",
        "Linux",
        "Mozilla",
        "Stroustrup",
        "Allman",
        "Whitesmiths",
        "GNU",
        "WebKit",
        "Custom"
      ]
    },
    "BreakBeforeConceptDeclarations": {
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "description": "clang-format 12\r\r The concept declaration style to use.",
          "type": "string",
          "enum": ["Never", "Allowed", "Always"]
        }
      ]
    },
    "BreakBeforeInheritanceComma": {
      "description": "clnag-format 5\r\r If true, in the class inheritance expression clang-format will break before : and , if there is multiple inheritance.",
      "type": "boolean"
    },
    "BreakBeforeTernaryOperators": {
      "description": "clang-format 3.7\r\r If true, ternary operators will be placed after line breaks.",
      "type": "boolean"
    },
    "BreakConstructorInitializers": {
      "description": "clang-format 5\r\r The constructor initializers style to use.",
      "type": "string",
      "enum": ["BeforeColon", "BeforeComma", "AfterColon"]
    },
    "BreakInheritanceList": {
      "description": "clang-format 7\r\r The inheritance list style to use.",
      "type": "string",
      "enum": ["BeforeColon", "BeforeComma", "AfterColon", "AfterComma"]
    },
    "BreakStringLiterals": {
      "description": "clang-format 3.9\r\r Allow breaking string literals when formatting.",
      "type": "boolean"
    },
    "BreakConstructorInitializersBeforeComma": {
      "description": "clang-format 3.8\r\r Always break constructor initializers before commas and align the commas with the colon.",
      "type": "boolean"
    },
    "ColumnLimit": {
      "description": "clang-format 3.7\r\r The column limit.",
      "type": "integer",
      "minimum": 0
    },
    "CommentPragmas": {
      "description": "clang-format 3.7\r\r A regular expression that describes comments with special meaning, which should not be split into lines or otherwise changed.",
      "type": "string"
    },
    "CompactNamespaces": {
      "description": "clang-format 5\r\r If true, consecutive namespace declarations will be on the same line. If false, each namespace is declared on a new line.",
      "type": "boolean"
    },
    "ConstructorInitializerAllOnOneLineOrOnePerLine": {
      "description": "clang-format 3.7\r\r This option is deprecated. See CurrentLine of PackConstructorInitializers.",
      "type": "boolean"
    },
    "ConstructorInitializerIndentWidth": {
      "description": "clang-format 3.7\r\r The number of characters to use for indentation of constructor initializer lists as well as inheritance lists.",
      "type": "integer",
      "minimum": 0
    },
    "ContinuationIndentWidth": {
      "description": "clang-format 3.7\r\r Indent width for line continuations.",
      "type": "integer",
      "minimum": 0
    },
    "Cpp11BracedListStyle": {
      "description": "clang-format 3.4\r\r If true, format braced lists as best suited for C++11 braced lists.",
      "type": "boolean"
    },
    "DeriveLineEnding": {
      "description": "clang-format 10\r\r Analyze the formatted file for the most used line ending (\r\n or \n). UseCRLF is only used as a fallback if none can be derived.\r\r This option is deprecated in clang-format 16. See DeriveLF and DeriveCRLF of LineEnding.",
      "type": "boolean"
    },
    "DerivePointerAlignment": {
      "description": "clang-format 3.7\r\r If true, analyze the formatted file for the most common alignment of & and *. Pointer and reference alignment styles are going to be updated according to the preferences found in the file. PointerAlignment is then used only as fallback.",
      "type": "boolean"
    },
    "DisableFormat": {
      "description": "clang-format 3.7\r\r Disables formatting completely.",
      "type": "boolean"
    },
    "EmptyLineAfterAccessModifier": {
      "description": "clang-format 13\r\r Defines when to put an empty line after access modifiers. EmptyLineBeforeAccessModifier configuration handles the number of empty lines between two access modifiers.",
      "type": "string",
      "enum": ["Never", "Leave", "Always"]
    },
    "EmptyLineBeforeAccessModifier": {
      "description": "clang-format 12\r\r Defines in which cases to put empty line before access modifiers.",
      "type": "string",
      "enum": ["LogicalBlock", "Never", "Leave", "Always"]
    },
    "ExperimentalAutoDetectBinPacking": {
      "description": "clang-format 3.7\r\r If true, clang-format detects whether function calls and definitions are formatted with one parameter per line.",
      "type": "boolean"
    },
    "FixNamespaceComments": {
      "description": "clang-format 5\r\r If true, clang-format adds missing namespace end comments for short namespaces and fixes invalid existing ones. This doesn't affect short namespaces, which are controlled by \"ShortNamespaceLines\".",
      "type": "boolean"
    },
    "ForEachMacros": {
      "description": "clang-format 3.7\r\r A vector of macros that should be interpreted as foreach loops instead of as function calls.",
      "type": "array",
      "items": {
        "type": "string",
        "examples": ["foreach", "Q_FOREACH", "BOOST_FOREACH"]
      }
    },
    "IfMacros": {
      "description": "clang-format 13\r\r A vector of macros that should be interpreted as conditionals instead of as function calls.",
      "type": "array",
      "items": {
        "type": "string",
        "examples": ["KJ_IF_MAYBE"]
      }
    },
    "IncludeBlocks": {
      "description": "clang-format 7\r\r Dependent on the value, multiple #include blocks can be sorted as one and divided based on category.",
      "type": "string",
      "enum": ["Regroup", "Preserve", "Merge"]
    },
    "IncludeCategories": {
      "description": "clang-format 7\r\r Regular expressions denoting the different #include categories used for ordering #includes. If none of the regular expressions match, INT_MAX is assigned as category.The main header for a source file automatically gets category 0. so that it is generally kept at the beginning of the #includes (https://llvm.org/docs/CodingStandards.html#include-style). However, you can also assign negative priorities if you have certain headers that always need to be first. \r There is a third and optional field SortPriority which can used while IncludeBlocks = IBS_Regroup to define the priority in which #includes should be ordered. The value of Priority defines the order of #include blocks and also allows the grouping of #includes of different priority. SortPriority is set to the value of Priority as default if it is not assigned.",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Regex": {
            "type": "string"
          },
          "Priority": {
            "type": "integer",
            "minimum": 0
          },
          "SortPriority": {
            "type": "integer",
            "minimum": 0
          },
          "CaseSensitive": {
            "type": "boolean"
          }
        },
        "required": ["Regex", "Priority"]
      }
    },
    "IncludeIsMainRegex": {
      "description": "clang-format 7\r\r Specify a regular expression of suffixes that are allowed in the file-to-main-include mapping.\rWhen guessing whether a #include is the \"main\" include (to assign category 0, see above), use this regex of allowed suffixes to the header stem. A partial match is done, so that: - \"\" means \"arbitrary suffix\" - \"$\" means \"no suffix\"\rFor example, if configured to \"(_test)?$\", then a header a.h would be seen as the \"main\" include in both a.cc and a_test.cc.",
      "type": "string"
    },
    "IncludeIsMainSourceRegex": {
      "description": "clang-format 7\r\r Specify a regular expression for files being formatted that are allowed to be considered \"main\" in the file-to-main-include mapping.\rBy default, clang-format considers files as \"main\" only when they end with: .c, .cc, .cpp, .c++, .cxx, .m or .mm extensions. For these files a guessing of \"main\" include takes place (to assign category 0, see above). This config option allows for additional suffixes and extensions for files to be considered as \"main\".\rBy default, clang-format considers files as \"main\" only when they end with: .c, .cc, .cpp, .c++, .cxx, .m or .mm extensions. For these files a guessing of \"main\" include takes place (to assign category 0, see above). This config option allows for additional suffixes and extensions for files to be considered as \"main\". ",
      "type": "string"
    },
    "IndentAccessModifiers": {
      "description": "clang-format 13\r\r Specify whether access modifiers should have their own indentation level.\rWhen false, access modifiers are indented (or outdented) relative to the record members, respecting the AccessModifierOffset. Record members are indented one level below the record. When true, access modifiers get their own indentation level. As a consequence, record members are always indented 2 levels below the record, regardless of the access modifier presence. Value of the AccessModifierOffset is ignored.",
      "type": "boolean"
    },
    "IndentCaseBlocks": {
      "description": "clang-format 11\r\r Indent case label blocks one level from the case label.\rWhen false, the block following the case label uses the same indentation level as for the case label, treating the case label the same as an if-statement. When true, the block gets indented as a scope block.",
      "type": "boolean"
    },
    "IndentCaseLabels": {
