                        "Database",
                        "EntityFramework",
                        "Cosmos",
                        "OData",
                        "HttpAgent",
                        "None"
                    ]
                },
                "dataCtor": {
                    "type": "string",
                    "title": "The access modifier for the generated 'Data' constructor.",
