          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "pattern": "parallel"
            },
            "entry": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/actionObject"
              }
            },
            "exit": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/actionObject"
              }
            },
            "invoke": {
              "$ref": "#/definitions/invokeArray"
            },
            "on": {
              "$ref": "#/definitions/transitionsObject"
            },
            "states": {
              "$ref": "#/definitions/statesObject"
            }
          },
          "required": ["states"]
        }
      ]
    },
    "atomicStateNode": {
      "allOf": [
        { "$ref": "#/definitions/baseStateNode" },
        {
          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "pattern": "atomic"
            },
            "entry": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/actionObject"
              }
            },
            "exit": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/actionObject"
              }
            },
            "invoke": {
              "$ref": "#/definitions/invokeArray"
            },
            "on": {
              "$ref": "#/definitions/transitionsObject"
            }
          },
          "required": ["on"]
        }
      ]
    },
    "historyStateNode": {
      "allOf": [
        { "$ref": "#/definitions/baseStateNode" },
        {
          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "pattern": "history"
            },
