          "type": "object"
        },
        "eventType": {
          "type": "string"
        },
        "source": {
          "type": "string"
        },
        "target": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      },
      "required": ["actions", "eventType", "source", "target"]
    },
    "invokeObject": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string"
        },
        "id": {
          "type": "string"
        },
        "src": {
          "type": "object",
          "properties": {
            "type": { "type": "string" }
          }
        },
        "autoForward": {
          "type": "boolean",
          "default": false
        }
      },
      "required": ["type", "id", "src"],
      "additionalProperties": false
    },
    "invokeArray": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/invokeObject"
      }
    },
    "functionObject": {
      "type": "object",
      "properties": {
        "$function": {
          "type": "string"
        }
      }
    },
    "order": {
      "type": "integer"
    }
  },
  "properties": {
    "id": {
      "title": "ID",
      "type": "string"
    },
    "initial": {
      "type": "string"
    },
    "key": {
      "type": "string"
    },
    "type": {
      "type": "string",
      "enum": ["compound", "parallel"]
    },
    "context": {
      "type": "object"
    },
