    },
    "entry": {
      "type": "array"
    },
    "exit": {
      "type": "array"
    },
    "order": {
      "$ref": "#/definitions/order"
    },
    "invoke": {
      "$ref": "#/definitions/invokeArray"
    },
    "version": {
      "type": "string"
    }
  },
  "required": ["id", "key", "type", "states"]
}

