          "type": "string",
          "description": "Provider name",
          "minLength": 1
        },
        "Dialect": {
          "type": "string",
          "title": "Dialect",
          "minLength": 1,
          "description": "Dialect",
          "anyOf": [
            {
              "enum": [
                "SqlServer",
                "SqlServer2012",
                "SqlServer2008",
                "SqlServer2005",
                "SqlServer2000",
                "Sqlite",
                "Postgres",
                "Oracle",
                "Oracle12c",
                "MySql",
                "Firebird"
              ]
            },
            {
              "type": "string"
            }
          ]
        },
        "Tables": {
          "type": "array",
          "uniqueItems": true,
          "title": "Tables",
          "description": "Generated table information",
          "items": {
            "$ref": "#/definitions/Table"
          }
        }
      }
    }
  },
  "description": "Serenity code generator (sergen) configuration",
  "id": "https://json.schemastore.org/sergen.json",
  "properties": {
    "Extends": {
      "type": "string",
      "title": "Extends",
      "minLength": 1,
      "description": "If specified, the settings in this file extends settings in a base file similar to tsconfig.json\nYou can also use Sergen defaults by specifying this like \"defaults@x.y.z\"",
      "anyOf": [
        {
          "type": "string",
          "pattern": "\\.json$"
        },
        {
          "enum": ["defaults@6.6.0"]
        }
      ]
    },
    "RootNamespace": {
      "type": "string",
      "description": "The root namespace for the target project. It is recommended to have this in sergen.json. If not there, it will be auto calculated from root namespace in CSPROJ file, or derived from project file name by removing .Web suffix. Generated code will be placed under this namespace and project's own types are assumed to be under this namespace as well",
      "minLength": 1
    },
    "DeclareJoinConstants": {
      "type": "boolean",
      "description": "If true, generated code will declare and use jFKTable type of constants for expressions in entities"
    },
    "EnableRowTemplates": {
      "type": "boolean",
      "description": "If true, enables RowTemplate class generation. This should only be used when Serenity.Pro.Coder is enabled in the project"
    },
    "EndOfLine": {
      "type": "string",
      "title": "EndOfLine",
      "description": "End of line character to use in generated files. If not specified, it will be auto detected from the environment",
      "enum": ["LF", "CRLF"]
    },
    "FileScopedNamespaces": {
      "type": "boolean",
      "description": "If true, generated code will use file scoped namespaces"
    },
    "ParseGlobalUsings": {
      "type": "boolean",
      "description": "If true, generated code will parse global usings from the current project"
    },
    "IncludeGlobalUsings": {
      "type": "array",
      "uniqueItems": true,
      "description": "If specified, generated code will assume these usings are in global using scope",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "ExcludeGlobalUsings": {
      "type": "array",
      "uniqueItems": true,
      "description": "If specified, generated code will assume these usings are not in global using scope even if they are in global using scope",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "OmitDefaultSchema": {
      "type": "boolean",
      "description": "If true, the default schema name, e.g. \"dbo\" for SQL Server won't be emitted in generated field expressions in Row.cs files. This is true by default only for MySql as in MySql schema names are actually database names"
    },
    "UseOriginAttribute": {
      "type": "boolean",
      "description": "If true, instead of using [Expression] attributes for foreign view fields, it will use Origin(nameof(jFK), nameof(FKRow.ViewField)) if the FKRow is already generated in the project. It will also use ForeignKey(typeof(FKRow)) type of foreign keys instead of strings"
    },
    "SaveGeneratedTables": {
      "type": "boolean",
      "description": "If true, generated table options like Identity, Module etc. will be saved to the Connections array in sergen.json after code generation. Default is true"
    },
    "ClientTypes": {
      "type": "object",
      "title": "ClientTypes",
      "description": "Client types code generation related configuration",
      "additionalProperties": false,
      "properties": {
        "OutDir": {
          "type": "string",
          "description": "The output directory for generated client types .cs files",
          "minLength": 1
        },
        "SourceGenerator": {
          "type": "boolean",
          "description": "If false, the client types source generator in Serenity.Pro.Coder will be disabled"
        }
      }
    },
    "MVC": {
      "type": "object",
      "title": "MVC",
      "description": "MVC (e.g. view locations) related configuration",
      "additionalProperties": false,
      "properties": {
        "UseRootNamespace": {
          "type": "boolean",
          "description": "If true, generated MVC views will be placed under the root namespace of the project"
        },
        "OutDir": {
          "type": "string",
          "description": "The output directory for MVC.cs",
          "minLength": 1
        },
        "SearchViewPaths": {
          "type": "array",
          "uniqueItems": true,
          "description": "View paths to search for, defaults to \"Modules\" and \"Views\". \"ProjectName\" is used instead of \"Modules\" if Razor SDK is used  for the project, e.g. a Razor class library",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "StripViewPaths": {
          "type": "array",
          "uniqueItems": true,
          "description": "Strip view paths from generated files. Defaults to \"Modules\", \"Views\". E.g. a subclass for Modules and Views won't be generated",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "SourceGenerator": {
          "type": "boolean",
          "description": "If false, the view paths source generator in Serenity.Pro.Coder will be disabled"
        }
      }
    },
    "ServerTypings": {
      "type": "object",
      "title": "ServerTypings",
      "description": "Server typings code generation related configuration",
      "additionalProperties": false,
      "properties": {
        "Assemblies": {
          "type": "array",
          "uniqueItems": true,
          "description": "Assemblies for server typings generation. Specify only if Sergen can't auto determine your project output file",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "OutDir": {
          "type": "string",
          "description": "The output directory for generated server typings files",
          "minLength": 1
        },
        "LocalTexts": {
          "type": "boolean",
          "description": "If true, local texts will be generated"
        },
        "ModuleReExports": {
          "type": "boolean",
          "description": "If true, module re-exports will be generated. Defaults to true"
        },
        "ModuleTypings": {
          "type": "boolean",
          "description": "If true, module typings will be generated. Defaults to true if you have \"module\" defined in tsconfig.json"
        },
        "NamespaceTypings": {
          "type": "boolean",
          "description": "If true, namespace typings will be generated. Defaults to true if you don't have \"module\" defined in tsconfig.json"
        },
        "SourceGenerator": {
          "type": "boolean",
          "description": "If false, the server typings source generator in Serenity.Pro.Coder will be disabled"
        }
      }
    },
    "Restore": {
      "type": "object",
      "title": "Restore",
      "description": "Sergen restore command related configuration",
      "additionalProperties": false,
      "properties": {
        "Include": {
          "type": "array",
          "uniqueItems": true,
          "description": "List of files (git ignore like) to include while restoring",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "Exclude": {
          "type": "array",
          "uniqueItems": true,
          "description": "List of files (git ignore like) to exclude while restoring",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "Typings": {
          "type": "boolean",
          "description": "Set false to disable namespace typings restore to typings/ folder"
        }
      }
    },
    "TSBuild": {
      "type": "object",
      "title": "TSBuild",
      "additionalProperties": true,
      "properties": {
        "EntryPoints": {
          "type": "array",
          "uniqueItems": true,
          "description": "List of entry point globs, default is \"**/Page.ts\", \"**/ScriptInit.ts\"",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "SourceGenerator": {
          "type": "boolean",
          "description": "Should the list of entry points, e.g. ESM be generated, only available with Serenity.Pro.Coder"
        }
      }
    },
    "Connections": {
      "type": "array",
      "uniqueItems": true,
      "title": "Connections",
      "description": "List of connections. It is only needed when it is desired to work / generated code based on a connection string that is not in appsettings.json",
      "items": {
        "$ref": "#/definitions/Connection"
      }
    },
    "KDiff3Path": {
      "type": "string",
      "description": "Path to KDiff3 executable. If not specified, it will be auto detected from the environment. (deprecated)",
      "minLength": 1
    },
    "TSCPath": {
      "type": "string",
      "description": "Full path to TypeScript compiler. It is assumed to be in path if not specified",
      "minLength": 1
    },
    "BaseRowClasses": {
      "type": "object",
      "title": "BaseRowClasses",
      "additionalProperties": false,
      "properties": {
        "ClassName": {
          "type": "string",
          "description": "The base class name",
          "minLength": 1
        },
        "Fields": {
          "type": "array",
          "uniqueItems": true,
          "description": "The base class fields that should exists in a table for this base class to be used",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "ForeignFieldSelection": {
      "type": "string",
      "title": "ForeignFieldSelection",
      "description": "The set of foreign fields to generate, default is NameOnly",
      "enum": ["None", "All", "NameOnly"]
    },
    "IncludeForeignFields": {
      "type": "array",
      "uniqueItems": true,
      "description": "A list of foreign fields to include in generated code. This could be used to include some additional fields This could be used to include some additional fields. Not so useful if ForeignFieldSelection is All",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "RemoveForeignFields": {
      "type": "array",
      "uniqueItems": true,
      "description": "A list of foreign fields to omit from generated code. This could be used to disable generating code for join fields like CreatedBy, ModifiedBy etc, so properties like CustomerCreatedBy, CustomerModifiedBy etc. won't be generated in OrderRow. Not so useful if ForeignFieldSelection is None or NameOnly",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "CustomTemplates": {
      "type": "string",
      "description": "The location of custom templates folder. The files in this folder will override the default scriban templates in Sergen. You may also include additional files to be generated. Their names must match the names at \nhttps://github.com/serenity-is/Serenity/tree/master/src/Serenity.Net.CodeGenerator/Templates",
      "minLength": 1
    },
    "CustomGenerate": {
      "type": "object",
      "title": "CustomGenerate",
      "description": "The relative paths of custom generated files",
      "additionalProperties": {
        "type": "string",
        "minLength": 1
      }
    },
    "CustomSettings": {
      "type": "object",
      "title": "CustomSettings",
      "description": "Custom settings to be passed to and used in custom templates"
    },
    "AppSettingFiles": {
      "type": "array",
      "uniqueItems": true,
      "description": "The list of appsettings.json files in order. Default is appsettings.json, appsettings.machine.json",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "UpgradeInfo": {
      "type": "object",
      "title": "UpgradeInfo",
      "description": "The upgrade / migration related information used by stargen to determine the base version of template used, and already applied upgrades",
      "additionalProperties": false,
      "properties": {
        "InitialType": {
          "type": "string",
          "title": "InitialType",
          "description": "Initial type of project. Available options are \"Community\" e.g. Serene, \"Premium\" e.g. StartSharp",
          "enum": ["Community", "Premium"]
        },
        "InitialVersion": {
          "type": "string",
          "description": "Version this project is created from. Used to determine which migrations should be applied to project (starting from)",
          "title": "InitialVersion",
          "pattern": "^(\\d+.)?(\\d+.)?(\\d+.)?(\\d+)?$",
          "minLength": 1
        },
        "AppliedUpgrades": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "title": "AppliedUpgrades",
          "uniqueItems": true,
          "description": "List of already applied upgrades if any"
        }
      }
    }
  },
  "title": "Serenity Code Generator (sergen) Configuration",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "definitions": {
    "webOptimizer": {
      "title": "web optimizer",
      "type": "object",
      "description": "Settings for WebOptimizer.Core",
      "properties": {
        "enableCaching": {
          "description": "Determines if the \"cache-control\" HTTP headers should be set and if conditional GET (304) requests should be supported. This could be helpful to disable while in development mode.",
          "type": "boolean"
        },
        "enableTagHelperBundling": {
          "description": "Determines if `<script>` and `<link>` elements should point to the bundled path or a reference per source file should be created. This is helpful to disable when in development mode.",
          "type": "boolean",
          "default": true
        }
      }
    },
    "cdn": {
      "title": "CDN",
      "type": "object",
      "description": "Definitions for WebEssentials.AspNetCore.CdnTagHelpers",
      "properties": {
        "url": {
          "description": "An absolute URL used as a prefix for static resources",
          "type": "string",
          "pattern": "^((//|https?://).+|)$"
        },
        "prefetch": {
          "description": "If true, injects a <link rel='dns-prefetch'> tag that speeds up DNS resolution to the CDN.",
          "type": "boolean",
          "default": true
        }
      }
    },
    "pwa": {
      "properties": {
        "cacheId": {
          "description": "The cache identifier of the service worker (can be any string). Change this property to force the service worker to reload in browsers.",
          "type": "string",
          "default": "v1.0"
        },
        "offlineRoute": {
          "description": "The route to the page to show when offline.",
          "type": "string",
          "default": "/offline.html"
        },
        "registerServiceWorker": {
          "description": "Determines if a script that registers the service worker should be injected into the bottom of the HTML page.",
          "type": "boolean",
          "default": true
        },
        "registerWebmanifest": {
          "description": "Determines if a meta tag that points to the web manifest should be inserted at the end of the head element.",
          "type": "boolean",
          "default": true
        },
        "routesToPreCache": {
          "description": "A comma separated list of routes to pre-cache when service worker installs in the browser.",
          "type": "string",
          "default": ""
        },
        "strategy": {
          "description": "Selects one of the predefined service worker types.",
          "enum": ["cacheFirst", "cacheFirstSafe", "minimal", "networkFirst"],
          "default": "cacheFirstSafe"
        }
      }
    },
    "ElmahIo": {
      "properties": {
        "ApiKey": {
          "description": "An elmah.io API key with the Messages | Write permission.",
          "type": "string",
          "pattern": "^[0-9a-f]{32}$"
        },
        "LogId": {
          "description": "The Id of the elmah.io log to store messages in.",
          "type": "string",
          "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
        },
        "Application": {
          "description": "An application name to put on all error messages.",
          "type": "string"
        },
        "HandledStatusCodesToLog": {
          "description": "A list of HTTP status codes (besides 404) to log even though no exception is thrown.",
          "type": "array",
          "items": {
            "type": "integer"
          }
        },
        "TreatLoggingAsBreadcrumbs": {
          "description": "Include log messages from Microsoft.Extensions.Logging as breadcrumbs.",
          "type": "boolean"
        },
        "HeartbeatId": {
          "description": "The Id of the elmah.io heartbeat to notify.",
          "type": "string",
          "pattern": "^[0-9a-f]{32}$"
        }
      },
      "required": ["ApiKey", "LogId"]
    },
    "protocols": {
      "description": "The protocols enabled on the endpoint.",
      "type": "string",
      "enum": [
        "None",
        "Http1",
        "Http2",
        "Http1AndHttp2",
        "Http3",
        "Http1AndHttp2AndHttp3"
      ]
    },
    "certificate": {
      "title": "certificate",
      "description": "Certificate configuration.",
      "type": "object",
      "properties": {
        "Path": {
          "description": "The certificate file path. If a file path is specified then the certificate will be loaded from the file system.",
          "type": "string"
        },
        "KeyPath": {
          "description": "The certificate key file path. Available in .NET 5 and later.",
          "type": "string"
        },
        "Password": {
          "description": "The certificate password used to access the private key.",
          "type": "string"
        },
        "Subject": {
          "description": "The certificate subject. If a subject is specified then the certificate will be loaded from the certificate store.",
          "type": "string"
        },
        "Store": {
          "description": "The certificate store name. Defaults to 'My'.",
          "type": "string",
          "default": "My"
        },
        "Location": {
          "description": "The certificate store location. Defaults to 'CurrentUser'.",
          "type": "string",
          "enum": ["LocalMachine", "CurrentUser"],
          "default": "CurrentUser"
        },
        "AllowInvalid": {
          "description": "A value indicating whether or not to load certificates that are considered invalid. Defaults to false.",
          "type": "boolean",
          "default": false
        }
      }
    },
    "sslProtocols": {
      "description": "Specifies allowable SSL protocols. Defaults to 'None' which allows the operating system to choose the best protocol to use, and to block protocols that are not secure. Unless your app has a specific reason not to, you should use this default. Available in .NET 5 and later.",
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["None", "Tls", "Tls11", "Tls12", "Tls13"],
        "default": "None"
      }
    },
    "clientCertificateMode": {
      "description": "Specifies the client certificate requirements for a HTTPS connection. Defaults to 'NoCertificate'. Available in .NET 5 and later.",
      "type": "string",
      "enum": ["NoCertificate", "AllowCertificate", "RequireCertificate"],
      "default": "NoCertificate"
    },
    "kestrel": {
      "title": "kestrel",
      "type": "object",
      "description": "ASP.NET Core Kestrel server configuration.",
      "properties": {
        "Endpoints": {
          "title": "endpoints",
          "description": "Endpoints that Kestrel listens to for network requests. Each endpoint has a name specified by its JSON property name.",
          "type": "object",
          "additionalProperties": {
            "title": "endpoint options",
            "description": "Kestrel endpoint configuration.",
            "type": "object",
            "properties": {
              "Url": {
                "description": "The scheme, host name, and port the endpoint will listen on. A Url is required.",
                "type": "string",
                "format": "uri"
              },
              "Protocols": {
                "$ref": "#/definitions/protocols"
              },
              "SslProtocols": {
                "$ref": "#/definitions/sslProtocols"
              },
              "Certificate": {
                "$ref": "#/definitions/certificate"
              },
              "ClientCertificateMode": {
                "$ref": "#/definitions/clientCertificateMode"
              },
              "Sni": {
                "title": "SNI",
                "description": "Server Name Indication (SNI) configuration. This enables the mapping of client requested host names to certificates and other TLS settings. Wildcard names prefixed with '*.', as well as a top level '*' are supported. Available in .NET 5 and later.",
                "type": "object",
                "additionalProperties": {
                  "title": "SNI options",
                  "description": "Endpoint SNI configuration.",
                  "type": "object",
                  "properties": {
                    "Protocols": {
                      "$ref": "#/definitions/protocols"
                    },
                    "SslProtocols": {
                      "$ref": "#/definitions/sslProtocols"
                    },
                    "Certificate": {
                      "$ref": "#/definitions/certificate"
                    },
                    "ClientCertificateMode": {
                      "$ref": "#/definitions/clientCertificateMode"
                    }
                  }
                }
              }
            },
            "required": ["Url"]
          }
        },
        "EndpointDefaults": {
          "title": "endpoint defaults",
          "description": "Default configuration applied to all endpoints. Named endpoint specific configuration overrides defaults.",
          "type": "object",
          "properties": {
            "Protocols": {
              "$ref": "#/definitions/protocols"
            },
            "SslProtocols": {
              "$ref": "#/definitions/sslProtocols"
            },
            "ClientCertificateMode": {
              "$ref": "#/definitions/clientCertificateMode"
            }
          }
        },
        "Certificates": {
          "title": "certificates",
          "description": "Certificates that Kestrel uses with HTTPS endpoints. Each certificate has a name specified by its JSON property name. The 'Default' certificate is used by HTTPS endpoints that haven't specified a certificate.",
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/certificate"
          }
        }
      }
    },
    "logLevelThreshold": {
      "description": "Log level threshold.",
      "type": "string",
      "enum": [
        "Trace",
        "Debug",
        "Information",
        "Warning",
        "Error",
        "Critical",
        "None"
      ]
    },
    "logLevel": {
      "title": "logging level options",
      "description": "Log level configurations used when creating logs. Only logs that exceeds its matching log level will be enabled. Each log level configuration has a category specified by its JSON property name. For more information about configuring log levels, see https://docs.microsoft.com/aspnet/core/fundamentals/logging/#configure-logging.",
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/logLevelThreshold"
      }
    },
    "logging": {
      "title": "logging options",
      "type": "object",
      "description": "Configuration for Microsoft.Extensions.Logging.",
      "properties": {
        "LogLevel": {
          "$ref": "#/definitions/logLevel"
        },
        "Console": {
          "properties": {
            "LogLevel": {
              "$ref": "#/definitions/logLevel"
            },
            "FormatterName": {
              "description": "Name of the log message formatter to use. Defaults to 'simple'.",
              "type": "string",
              "default": "simple"
            },
            "FormatterOptions": {
              "title": "formatter options",
              "description": "Log message formatter options. Additional properties are available on the options depending on the configured formatter. The formatter is specified by FormatterName.",
              "type": "object",
              "properties": {
                "IncludeScopes": {
                  "description": "Include scopes when true. Defaults to false.",
                  "type": "boolean",
                  "default": false
                },
                "TimestampFormat": {
                  "description": "Format string used to format timestamp in logging messages. Defaults to null.",
                  "type": "string"
                },
                "UseUtcTimestamp": {
                  "description": "Indication whether or not UTC timezone should be used to for timestamps in logging messages. Defaults to false.",
                  "type": "boolean",
                  "default": false
                }
              }
            },
            "LogToStandardErrorThreshold": {
              "description": "The minimum level of messages are written to Console.Error.",
              "$ref": "#/definitions/logLevelThreshold"
            }
          }
        },
        "EventSource": {
          "properties": {
            "LogLevel": {
              "$ref": "#/definitions/logLevel"
            }
          }
        },
        "Debug": {
          "properties": {
            "LogLevel": {
              "$ref": "#/definitions/logLevel"
            }
          }
        },
        "EventLog": {
          "properties": {
            "LogLevel": {
              "$ref": "#/definitions/logLevel"
            }
          }
        },
        "ElmahIo": {
          "properties": {
            "LogLevel": {
              "$ref": "#/definitions/logLevel"
            }
          }
        },
        "ElmahIoBreadcrumbs": {
          "properties": {
            "LogLevel": {
              "$ref": "#/definitions/logLevel"
            }
          }
        }
      },
      "additionalProperties": {
        "title": "provider logging settings",
        "type": "object",
        "description": "Logging configuration for a provider. The provider name must match the configuration's JSON property property name.",
        "properties": {
          "LogLevel": {
            "$ref": "#/definitions/logLevel"
          }
        }
      }
    },
    "allowedHosts": {
      "description": "ASP.NET Core host filtering middleware configuration. Allowed hosts is a semicolon-delimited list of host names without port numbers. Requests without a matching host name will be refused. Host names may be prefixed with a '*.' wildcard, or use '*' to allow all hosts.",
      "type": "string"
    },
    "connectionStrings": {
      "title": "connection string options",
      "description": "Connection string configuration. Get connection strings with the IConfiguration.GetConnectionString(string) extension method.",
      "type": "object",
      "additionalProperties": {
        "description": "Connection string configuration. Each connection string has a name specified by its JSON property name.",
        "type": "string"
      }
    },
    "NLog": {
      "title": "NLog options",
      "type": "object",
      "description": "NLog configuration",
      "default": {},
      "properties": {
        "autoReload": {
          "type": "boolean",
          "description": "Automatically reload the NLog configuration when notified that appsettings.json file has changed.",
          "default": false
        },
        "throwConfigExceptions": {
          "type": ["boolean", "null"],
          "description": "Throws an exception when there is a config error? If not set, then throwExceptions will be used for this setting.",
          "default": false
        },
        "throwExceptions": {
          "type": "boolean",
          "description": "Throws an exception when there is an error. For unit testing only and advanced troubleshooting.",
          "default": false
        },
        "internalLogLevel": {
          "type": "string",
          "description": "The minimal log level for the internal logger.",
          "enum": ["Trace", "Debug", "Info", "Warn", "Error", "Fatal", "Off"],
          "default": "Off"
        },
        "internalLogFile": {
          "type": "string",
          "description": "Write internal log to the specified filepath"
        },
        "internalLogToConsole": {
          "type": "boolean",
          "description": "Write internal log to a console",
          "default": "false"
        },
        "internalLogToConsoleError": {
          "type": "boolean",
          "description": "Write internal log to a console with error stream",
          "default": "false"
        },
        "globalThreshold": {
          "type": "string",
          "description": "Log events below this threshold are not logged.",
          "enum": ["Trace", "Debug", "Info", "Warn", "Error", "Fatal", "Off"],
          "default": "Off"
        },
        "autoShutdown": {
          "type": "boolean",
          "description": "Automatically call `LogFactory.Shutdown` on AppDomain.Unload or AppDomain.ProcessExit",
          "default": "true"
        },
        "extensions": {
          "type": "array",
          "description": "Load NLog extension packages for additional targets and layouts",
          "default": [],
          "items": {
            "title": "extension",
            "type": "object",
            "description": "",
            "default": {},
            "properties": {
              "assembly": {
                "type": "string",
                "description": "Assembly Name of the NLog extension package."
              },
              "prefix": {
                "type": "string",
                "description": "Appends prefix to all type-names loaded from the assembly",
                "default": ""
              },
              "assemblyFile": {
                "type": "string",
                "description": "Absolute filepath to the Assembly-file of the NLog extension package.",
                "default": ""
              }
            }
          }
        },
        "variables": {
          "title": "variables",
          "type": "object",
          "description": "Key-value pair of variables",
          "propertyNames": {
            "pattern": "^[A-Za-z0-9_.-]+$"
          },
          "patternProperties": {
            ".*": {
              "type": ["number", "string", "boolean"]
            }
          }
        },
        "targetDefaultWrapper": {
          "title": "default wrapper",
          "type": "object",
          "description": "Wrap all defined targets with this custom target wrapper.",
          "default": {},
          "required": ["type"],
          "properties": {
            "type": {
              "type": "string",
              "description": ""
            }
          }
        },
        "targets": {
          "title": "targets",
          "type": "object",
          "description": "",
          "default": {},
          "properties": {
            "async": {
              "type": "boolean",
              "description": "Wrap all defined targets using AsyncWrapper with OverflowAction=Discard for better performance."
            }
          }
        },
        "rules": {
          "oneOf": [
            {
              "type": "array",
              "description": "",
              "default": [],
              "items": {
                "$ref": "#/definitions/NLogRulesItem"
              }
            },
            {
              "title": "rules",
              "type": "object",
              "propertyNames": {
                "pattern": "^[0-9]+$"
              },
              "patternProperties": {
                ".*": {
                  "$ref": "#/definitions/NLogRulesItem"
                }
              }
            }
          ]
        }
      }
    },
    "NLogRulesItem": {
      "title": "NLog rule item",
      "type": "object",
      "description": "Redirect LogEvents from matching Logger objects to specified targets",
      "default": {},
      "required": ["logger"],
      "properties": {
        "logger": {
          "type": "string",
          "description": "Match Logger objects based on their Logger-name. Can use wildcard characters ('*' or '?')."
        },
        "ruleName": {
          "type": "string",
          "description": "Rule identifier to allow rule lookup with Configuration.FindRuleByName and Configuration.RemoveRuleByName."
        },
        "level": {
          "anyOf": [
            {
              "type": "string",
              "description": "",
              "enum": ["Trace", "Debug", "Info", "Warn", "Error", "Fatal"]
            },
            {
              "type": "string"
            }
          ]
        },
        "levels": {
          "type": "string",
          "description": "Comma separated list of levels that this rule matches."
        },
        "minLevel": {
          "anyOf": [
            {
              "type": "string",
              "description": "",
              "enum": ["Trace", "Debug", "Info", "Warn", "Error", "Fatal"]
            },
            {
              "type": "string"
            }
          ]
        },
        "maxLevel": {
          "anyOf": [
            {
              "type": "string",
              "description": "",
              "enum": ["Trace", "Debug", "Info", "Warn", "Error", "Fatal"]
            },
            {
              "type": "string"
            }
          ]
        },
        "finalMinLevel": {
          "anyOf": [
            {
              "type": "string",
              "description": "",
              "enum": ["Trace", "Debug", "Info", "Warn", "Error", "Fatal"]
            },
            {
              "type": "string"
            }
          ]
        },
        "writeTo": {
          "type": "string",
          "description": "Name or names of a target - separated by comma. Remove this property for sending events to the blackhole."
        },
        "final": {
          "type": "boolean",
          "description": "Ignore further rules if this one matches.",
          "default": false
        },
        "enabled": {
          "type": "boolean",
          "description": "",
          "default": true
