          "pattern": "^(?:(?:>=|>|<=|<)\\d+\\.\\d+\\.\\d+(?:[+-]\\S+)?\\s*)+$"
        },
        {
          "type": "string",
          "examples": ["^1.0.0"],
          "pattern": "^\\^\\d+\\.\\d+\\.\\d+(?:[+-]\\S+)?$"
        }
      ]
    },
    "dependency": {
      "oneOf": [
        {
          "$ref": "#/definitions/versionConstraint",
