          "type": "string"
        },
        "providers": {
          "type": "string"
        },
        "database": {
          "type": "string"
        },
        "migrations": {
          "type": "string"
        },
        "seeds": {
          "type": "string"
        },
        "resources": {
          "type": "string"
        },
        "views": {
          "type": "string"
        },
        "start": {
          "type": "string"
        },
        "tmp": {
          "type": "string"
