{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "https://raw.githubusercontent.com/ansible/ansible-rulebook/main/ansible_rulebook/schema/ruleset_schema.json",
    "type": "array",
    "items": {
        "$ref": "#/$defs/ruleset"
    },
    "minItems": 1,
    "examples": [
        "rulebooks/*.yml",
        "rulebooks/*.yaml"
    ],
    "$defs": {
        "ruleset": {
            "type": "object",
            "properties": {
                "default_events_ttl": {
                    "type": "string",
                    "pattern": "^\\d+\\s(seconds?|minutes?|hours?|days?)$"
                },
                "hosts": {
                    "type": "string"
                },
                "gather_facts": {
                    "type": "boolean",
                    "default": false
                },
                "match_multiple_rules": {
                    "type": "boolean",
                    "default": false
                },
                "name": {
                    "type": "string"
                },
                "execution_strategy": {
                    "type": "string",
                    "enum": [
                        "parallel",
                        "sequential"
                    ],
                    "default": "sequential"
                },
                "sources": {
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/source"
                    }
                },
                "rules": {
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/rule"
                    }
                }
            },
            "required": [
                "hosts",
                "sources",
                "rules"
            ],
            "additionalProperties": false
        },
        "source": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string"
                },
                "filters": {
                    "type": "array",
                    "items": {
                        "type": "object"
                    }
                }
            },
            "additionalProperties": {
                "oneOf": [
                    {
                        "type": "object"
                    },
                    {
                        "type": "null"
                    }
                ]
            }
        },
        "throttle": {
            "type": "object",
            "oneOf": [
                {
                    "required": [
                        "once_within",
                        "group_by_attributes"
                    ]
                },
                {
                    "required": [
                        "once_after",
                        "group_by_attributes"
                    ]
                }
            ],
            "properties": {
                "once_within": {
                    "type": "string",
                    "pattern": "^\\d+\\s(milliseconds?|seconds?|minutes?|hours?|days?)$"
                },
                "once_after": {
                    "type": "string",
                    "pattern": "^\\d+\\s(milliseconds?|seconds?|minutes?|hours?|days?)$"
                },
                "group_by_attributes": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
