          "type": "integer",
          "default": -1,
          "minimum": -1
        },
        "description": {
          "description": "A short description of the artifact location.",
          "$ref": "#/definitions/message"
        },
        "properties": {
          "description": "Key/value pairs that provide additional information about the artifact location.",
          "$ref": "#/definitions/propertyBag"
        }
      }
    },
