          "description": "Indent size. [JS,CSS,HTML]",
          "type": "integer",
          "default": 4
        },
        "indent_char": {
          "description": "Indentation character. [JS,CSS,HTML]",
          "type": "string",
          "default": " ",
          "maxLength": 1
        },
