        },
        "end_with_newline": {
          "description": "Ensure newline at end of file. [JS,CSS,HTML]",
          "type": "boolean",
          "default": false
        },
        "preserve_newlines": {
          "description": "Preserve line-breaks. [JS,CSS,HTML]",
          "type": "boolean",
          "default": true
        }
      }
    },
    "HJProperties": {
      "type": "object",
      "properties": {
