              "dispute_write",
              "edit_link_write",
              "elements_write",
              "event_read",
              "file_read",
              "file_write",
              "invoice_read",
              "invoice_write",
              "issuing_authorization_read",
              "issuing_authorization_write",
              "issuing_card_read",
              "issuing_card_write",
              "issuing_cardholder_read",
              "issuing_cardholder_write",
              "issuing_dispute_read",
              "issuing_dispute_write",
              "issuing_transaction_read",
              "issuing_transaction_write",
              "mandate_read",
