{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "definitions": {
    "alias": {
      "type": "string",
      "description": "domain names (optionally including subdomains) added to the account, or a string for a suffixed URL using .now.sh or a Custom Deployment Suffix"
    },
    "env": {
      "type": "object",
      "description": "environment keys and values",
      "additionalProperties": {
        "type": "string"
      }
    }
  },
  "description": "ZEIT Now project configuration file",
  "id": "https://json.schemastore.org/now.json",
  "properties": {
    "name": {
      "type": "string",
      "description": "name for the deployment",
      "maxLength": 52
    },
    "version": {
      "enum": [1, 2],
      "description": "the Now Platform version that the deployment should use and is known to work with",
      "default": 2
    },
    "alias": {
      "oneOf": [
        {
          "type": "array",
          "maxItems": 64,
          "items": {
            "$ref": "#/definitions/alias"
          }
        },
        {
          "$ref": "#/definitions/alias"
        }
      ]
    },
    "scope": {
      "type": "string",
      "description": "an ID or slug for teams, or an email address, username, or ID for users"
    },
    "env": {
      "$ref": "#/definitions/env",
      "description": "environment variables passed to the invoked Serverless Functions"
    },
    "build": {
      "type": "object",
      "properties": {
        "env": {
          "$ref": "#/definitions/env",
          "description": "environment variables passed to the Build processes"
        }
      }
    },
    "builds": {
      "type": "array",
      "description": "a list of build descriptions whose src references valid source files",
      "items": {
        "type": "object",
        "description": "build description",
        "required": ["src", "use"],
        "properties": {
          "src": {
            "type": "string",
            "description": "A glob expression or pathname. If more than one file is resolved, one build will be created per matched file. It can include `*` and `**`."
          },
          "use": {
            "type": "string",
            "description": "A npm module to be installed by the build process. It can include a semver compatible version (e.g.: `@org/proj@1`)."
          },
          "config": {
            "type": "object",
            "description": "An object including arbitrary metadata to be passed to the Builder."
          }
        }
      }
    },
    "routes": {
      "type": "array",
      "description": "a list of route definitions",
      "items": {
        "type": "object",
        "description": "route definition",
        "oneOf": [
          {
            "required": ["src"]
          },
          {
            "required": ["handle"]
          }
        ],
        "properties": {
          "src": {
            "type": "string",
            "description": "A PCRE-compatible regular expression that matches each incoming pathname (excluding querystring)."
          },
          "methods": {
            "type": "array",
            "description": "A set of HTTP method types. If no method is provided, requests with any HTTP method will be a candidate for the route.",
            "items": {
              "enum": [
                "GET",
                "HEAD",
                "POST",
                "PUT",
                "DELETE",
                "CONNECT",
                "OPTIONS",
                "TRACE",
                "PATCH"
              ]
            }
          },
          "dest": {
            "type": "string",
            "description": "A destination pathname or full URL, including querystring, with the ability to embed capture groups as $1, $2…"
          },
          "headers": {
            "type": "object",
            "description": "A set of headers to apply for responses.",
            "additionalProperties": {
              "type": "string"
            }
          },
          "status": {
            "type": "integer",
            "description": "A status code to respond with. Can be used in tandem with `Location:` header to implement redirects.",
            "minimum": 100,
            "maximum": 599
          },
          "continue": {
            "type": "boolean",
            "description": "A boolean to change matching behavior. If true, routing will continue even when the src is matched."
          },
          "handle": {
            "type": "string",
            "enum": ["filesystem"]
          }
        }
      }
    },
    "regions": {
      "type": "array",
      "description": "the deployment regions of the Serverless Functions that get created as a result of the build steps",
      "items": {
        "description": "region identifier",
        "type": "string"
      }
    },
    "public": {
      "type": "boolean",
      "description": "When set to true, both the source view and logs view will be publicly accessible (when the user is authenticated with ZEIT)."
    },
    "github": {
      "type": "object",
      "description": "Git integration options",
      "properties": {
        "enabled": {
          "type": "boolean",
          "description": "When set to false, Now for GitHub will not deploy the given project regardless of the GitHub app being installed.",
          "default": true
        },
        "autoAlias": {
          "type": "boolean",
          "description": "When set to false, Now for GitHub will not apply the alias upon merge.",
          "default": true
        },
        "silent": {
          "type": "boolean",
          "description": "When set to true, Now for GitHub will stop commenting on pull requests and commits.",
          "default": false
        },
        "autoJobCancelation": {
          "type": "boolean",
          "description": "When set to false, Now for GitHub will always build pushes in sequence without cancelling a build for the most recent commit.",
          "default": true
        }
      }
    }
  },
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/samtrc.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {
    "level_type": {
      "enum": ["error", "warn", "info", "off"]
    },
    "naming_type": {
      "enum": [
        "PascalCase",
        "camelCase",
        "kebab-case",
        "snake_case",
        "SCREAMING_SNAKE_CASE"
      ]
    }
  },
  "properties": {
    "extends": {
      "description": "The name of the configuration file to extend from, used to determine the default rules to apply",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "enum": ["recommended", "strict"]
        }
      ]
    },
    "rules": {
      "description": "Configuration for linter rules for the current project",
      "type": "array",
      "items": {
        "oneOf": [
          {
            "description": "Configure whether model types (e.g. record and service) must be in a separate file from their providers and consumers",
            "type": "object",
            "required": ["type"],
            "properties": {
              "type": {
                "const": "split-model-and-providers"
              },
              "level": {
                "$ref": "#/definitions/level_type"
              }
            },
            "additionalProperties": false
          },
          {
            "description": "Configure naming rules which apply to all types in the project",
            "type": "object",
            "required": ["type"],
            "properties": {
              "type": {
                "const": "naming-conventions"
              },
              "level": {
                "$ref": "#/definitions/level_type"
              },
              "record": {
                "$ref": "#/definitions/naming_type"
              },
              "recordField": {
                "$ref": "#/definitions/naming_type"
              },
              "enum": {
                "$ref": "#/definitions/naming_type"
              },
              "enumValue": {
                "$ref": "#/definitions/naming_type"
              },
              "typeAlias": {
                "$ref": "#/definitions/naming_type"
              },
              "service": {
                "$ref": "#/definitions/naming_type"
              },
              "serviceOperation": {
                "$ref": "#/definitions/naming_type"
              },
              "serviceOperationParameter": {
                "$ref": "#/definitions/naming_type"
              },
              "provider": {
                "$ref": "#/definitions/naming_type"
              },
              "package": {
                "$ref": "#/definitions/naming_type"
              },
              "fileName": {
                "$ref": "#/definitions/naming_type"
              }
            },
            "additionalProperties": false
          }
        ]
      }
    }
  },
  "required": ["extends"],
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/sponge-mixins.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "mixin_class": {
      "type": "string",
      "description": "The dot-separated path to the mixin class relative to the specified package. The class must be annotated with @Mixin"
    },
    "injector_options": {
      "type": "object",
      "description": "Injection options",
      "properties": {
        "defaultRequire": {
          "type": "integer",
          "minimum": 0,
          "description": "Sets the default minimum of injections that must be successfully applied per injector",
          "default": 0
        },
        "defaultGroup": {
          "type": "string",
          "description": "Sets the default injector group",
          "default": "default"
        },
        "injectionPoints": {
          "type": "array",
          "description": "Registers injection points for this configuration",
          "items": {
            "type": "string"
          }
        },
        "maxShiftBy": {
          "type": "integer",
          "minimum": 0,
          "maximum": 5,
          "default": 5,
          "description": "Sets the maximum allowed number of opcodes that can be shifted in @At annotations. This is hard capped at 5"
        }
      }
    },
    "overwrite_options": {
      "type": "object",
      "description": "Overwrite options",
      "properties": {
        "conformVisibility": {
          "type": "boolean",
          "description": "Sets whether the visibility of overwritten methods should be conformed to the target class"
        },
        "requireAnnotations": {
          "type": "boolean",
          "default": true,
          "description": "Sets whether overwriting methods must explicitly be declared through @Overwrite annotations"
        }
      }
    }
  },
  "properties": {
    "parent": {
      "type": "string",
      "description": "The name of a parent configuration that options get inherited from"
    },
    "target": {
      "type": "string",
      "description": "Target selector. Either the specifies the phase directly or use \"@env(PHASE)\" separated by '&', '\\', or ' '"
    },
    "minVersion": {
      "type": "string",
      "pattern": "^(\\d{1,5})(?:\\.(\\d{1,5})(?:\\.(\\d{1,5})(?:\\.(\\d{1,5}))?)?)?(-[a-zA-Z0-9_\\-]+)?$",
      "description": "Minimum version of the mixin subsystem required for this configuration"
    },
    "compatibilityLevel": {
      "type": "string",
      "description": "Minimum compatibility level required for mixins in this set"
    },
    "required": {
      "type": "boolean",
      "description": "Determines whether mixin failures in this configuration are considered terminal and stop the game"
    },
    "priority": {
      "type": "integer",
      "description": "The priority of this configuration. Will be inherited if smaller than 0",
      "default": -1
    },
    "mixinPriority": {
      "type": "integer",
      "description": "Default mixin priority for this configuration. Will be inherited if smaller than 0",
      "default": -1
    },
    "package": {
      "type": "string",
      "description": "The target package where the mixin classes reside"
    },
    "mixins": {
      "type": "array",
      "description": "Mixin classes to load in all environments. Class names get prepended with the specified package",
      "items": {
        "$ref": "#/definitions/mixin_class"
      }
    },
    "client": {
      "type": "array",
      "description": "Mixin classes to load ONLY on client. Class names get prepended with the specified package",
      "items": {
        "$ref": "#/definitions/mixin_class"
      }
    },
    "server": {
      "type": "array",
      "description": "Mixin classes to load ONLY on server. Class names get prepended with the specified package",
      "items": {
        "$ref": "#/definitions/mixin_class"
      }
    },
    "setSourceFile": {
      "type": "boolean",
      "description": "Sets whether targets' source files will be updated to the mixin source file"
    },
    "refmap": {
      "type": "string",
      "description": "The path to the reference map resource to use for this configuration"
    },
    "verbose": {
      "type": "boolean",
      "description": "Increases log detail level from DEBUG to INFO",
      "default": false
    },
    "plugin": {
      "type": "string",
      "description": "Name of the mixin config plugin to use for this config"
    },
    "injectors": {
      "$ref": "#/definitions/injector_options"
    },
    "overwrites": {
      "$ref": "#/definitions/overwrite_options"
    }
  },
  "required": ["package"],
  "type": "object"
}

