      "type": "object",
      "patternProperties": {
        "^[^\\+#$\\s\\.]+$": {
          "type": "object",
          "required": ["value"],
          "properties": {
            "value": {
              "type": ["number", "string", "boolean"]
            }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
