{
  "$id": "https://json.schemastore.org/backportrc.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "description": "A Backport config schema",
  "properties": {
    "repoName": {
      "description": "A repo name for the current project\nhttps://github.com/sqren/backport/blob/main/docs/config-file-options.md#reponame-required",
      "type": "string",
      "minLength": 1,
      "examples": ["kibana"]
    },
    "repoOwner": {
      "description": "A repo owner for the current project\nhttps://github.com/sqren/backport/blob/main/docs/config-file-options.md#repoowner-required",
      "type": "string",
      "minLength": 1,
      "examples": ["elastic"]
    },
    "targetBranchChoices": {
      "description": "Target branches for the current project\nhttps://github.com/sqren/backport/blob/main/docs/config-file-options.md#targetbranchchoices-required",
      "type": "array",
      "uniqueItems": true,
      "items": {
        "description": "A target branch for the current project\nhttps://github.com/sqren/backport/blob/main/docs/config-file-options.md#targetbranchchoices-required",
        "oneOf": [
          {
            "type": "string",
            "minLength": 1,
            "examples": ["6.2"]
          },
          {
            "title": "target branch",
            "type": "object",
            "required": ["name", "checked"],
            "properties": {
              "name": {
                "description": "A target branch for the current project\nhttps://github.com/sqren/backport/blob/main/docs/config-file-options.md#targetbranchchoices-required",
                "type": "string",
                "minLength": 1,
                "examples": ["6.3"]
              },
              "checked": {
                "description": "Whether to pre-select a target branch for the current project\nhttps://github.com/sqren/backport/blob/main/docs/config-file-options.md#targetbranchchoices-required",
                "type": "boolean"
              }
            },
            "additionalProperties": false
          }
        ]
      }
    },
    "upsteam": {
      "description": "Identifier for the GitHub project as `{owner}/{repoName}`",
      "type": "string"
    },
    "branches": {
      "description": "Branches to backport to",
      "type": "array",
      "items": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "type": "object",
            "properties": {
              "name": {
                "type": "string"
              },
              "checked": {
                "type": "boolean"
              }
            },
            "required": ["name", "checked"]
          }
        ]
      }
    },
    "labels": {
      "description": "Labels that will be added to the pull request",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "all": {
      "description": "Whether to only show the current user's commits or commits from anyone",
      "type": "boolean"
    }
  },
  "required": ["repoName", "repoOwner", "targetBranchChoices"],
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "id": "https://json.schemastore.org/servicehub.config.schema.json",
  "properties": {
    "controller": {
      "type": "object",
      "description": "Specifies the location of the controller executable and activation parameters.",
      "required": ["executable"],
      "properties": {
        "contextEnvironmentVariables": {
          "type": "array",
          "description": "Array of environment variable names. These variables are mixed-up into hash that determines the location service pipe name. The order is significant.",
          "items": {
            "type": "string"
          },
          "uniqueItems": true
        },
        "executable": {
          "type": "string"
        },
        "args": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "additionalEnvironmentVariables": {
          "type": "object",
          "description": "An object with properties like \"environment variable name\": \"value\" that describes what environment variables to set for the Hub Controller.",
          "additionalProperties": false,
          "patternProperties": {
            "^[A-Za-z0-9_/\\.]+$": {
              "type": "string",
              "description": "The value of the environment variable to set."
            }
          }
        }
      },
      "hosts": {
        "type": "object",
        "required": ["rootDir"],
        "properties": {
          "rootDir": {
            "type": "string",
            "description": "The path to the directory immediately under which are folders that contain *.servicehub.host.json files."
          }
        }
      },
      "services": {
        "type": "object",
        "required": ["rootDir"],
        "properties": {
          "rootDir": {
            "type": "string",
            "description": "The path to the directory immediately under which are folders that contain *.servicehub.service.json files."
          },
          "discoveryServices": {
            "description": "Service names of optional discovery service modules. Controller will use them to locate a service which it cannot find in the services folder.",
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        }
      }
    }
  },
  "required": ["controller", "hosts", "services"],
  "title": "Microsoft ServiceHub Configuration",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "definitions": {
    "app": {
      "type": "object",
      "properties": {
        "script": {
          "type": "string",
          "description": "Path of the script to launch"
        },
        "name": {
          "type": "string",
          "description": "Process name in the process list. Defaults to script filename without the extension (app for app.js)"
        },
        "cwd": {
          "type": "string",
          "description": "Current working directory to start the process with. Defaults to CWD of the current environment (from your shell)"
        },
        "args": {
          "description": "Arguments to pass to the script",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "interpreter": {
          "type": "string",
          "description": "Interpreter absolute path. Defaults to node"
        },
        "interpreter_args": {
          "description": "Options to pass to the interpreter",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "error_file": {
          "type": "string",
          "description": "File path for stderr (each line is appended to this file)",
          "default": "~/.pm2/logs/<app_name>-error.err"
        },
        "out_file": {
          "type": "string",
          "description": "File path for stdout (each line is appended to this file)",
          "default": "~/.pm2/logs/<app_name>-out.log"
        },
        "combine_logs": {
          "type": "boolean",
          "description": "If set to true, avoid to suffix logs file with the process id",
          "default": "/dev/null"
        },
        "merge_logs": {
          "type": "boolean",
          "description": "Alias to combine_logs"
        },
        "pid_file": {
          "type": "string",
          "description": "File path where the pid of the started process is written by pm2. Defaults to ~/.pm2/pids/app_name-id.pid"
        },
        "disable_logs": {
          "type": "boolean",
          "description": "Disable all logs storage"
        },
        "log_type": {
          "type": "string",
          "description": "Define a specific log output type",
          "enum": ["json"]
        },
        "log_date_format": {
          "type": "string",
          "description": "Format for log timestamps in moment.js format (eg YYYY-MM-DD HH:mm Z)"
        },
        "env": {
          "type": "object",
          "description": "Specify environment variables to be injected",
          "additionalProperties": {
            "type": "string"
          }
        },
        "env_": {
          "type": "object",
          "description": "Specify environment variables to be injected (when passing --env)",
          "additionalProperties": {
            "type": "string"
          }
        },
        "max_memory_restart": {
          "type": "number",
          "description": "Restart the app if an amount of memory is exceeded (format: /0-9?/ K for KB, 'M' for MB, 'G' for GB, default to B)"
        },
        "restart_delay": {
          "type": "number",
          "description": "Time in ms to wait before restarting a crashing app"
        },
        "source_map_support": {
          "type": "boolean",
          "description": "Enable or disable the source map support",
          "default": true
        },
        "disable_source_map_support": {
          "type": "boolean",
          "description": "Enable or disable the source map support"
        },
        "wait_ready": {
