        "TcpNoDelay": {
          "type": "boolean",
          "default": true
        },
        "TcpQuickAck": {
          "type": "boolean",
          "default": false
        },
        "TcpSendBufferSize": {
          "type": "integer"
        },
        "TcpReceiveBufferSize": {
          "type": "integer"
        },
        "EnableDomainSockets": {
          "type": "boolean",
          "default": true
        }
      },
      "additionalProperties": false
    }
