                                "$ref": "#/definitions/disable"
                              }
                            }
                          },
                          {
                            "title": "action",
                            "type": "object",
                            "additionalProperties": false,
                            "description": "Defines a TS code builder task.",
                            "required": [
                              "type",
                              "typescriptVersion",
                              "id",
                              "generateId"
                            ],
                            "properties": {
                              "type": {
                                "type": "string",
                                "const": "build",
                                "description": "Type of action to apply."
                              },
                              "typescriptVersion": {
                                "$ref": "#/definitions/version",
