      "type": "number",
      "description": "The `BUILD_ID` to use for this task.",
      "default": 0
    },
    "generateId": {
      "type": "number",
      "description": "The `GENERATE_ID` to use for this task.",
      "default": 0
    },
    "disable": {
      "type": "boolean",
      "description": "Determines if this task is disabled.",
      "default": true
    }
  },
