{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://dprint.dev/schemas/v0.json",
  "title": "dprint configuration file",
  "description": "Schema for a dprint configuration file.",
  "type": "object",
  "properties": {
    "$schema": {
      "description": "The JSON schema reference. Normally you shouldn't bother to provide this as the dprint vscode editor extension will handle constructing the schema for you based on the plugins provided.",
      "type": "string"
    },
    "incremental": {
      "description": "Whether to format files only when they change.",
      "type": "boolean",
      "default": true
    },
    "extends": {
      "description": "Configurations to extend.",
      "anyOf": [{
        "description": "A file path or url to a configuration file to extend.",
        "type": "string"
      }, {
        "description": "A collection of file paths and/or urls to configuration files to extend.",
        "type": "array",
        "items": {
          "type": "string"
        }
      }]
    },
    "lineWidth": {
      "description": "The width of a line the printer will try to stay under. Note that the printer may exceed this width in certain cases.",
      "type": "number"
    },
    "indentWidth": {
      "description": "The number of characters for an indent.",
      "type": "number"
    },
    "useTabs": {
      "description": "Whether to use tabs (true) or spaces (false) for indentation.",
      "type": "boolean"
    },
    "newLineKind": {
      "description": "The kind of newline to use.",
      "type": "string",
      "oneOf": [
        {
          "const": "auto",
          "description": "For each file, uses the newline kind found at the end of the last line."
        },
        {
          "const": "crlf",
          "description": "Uses carriage return, line feed."
        },
        {
          "const": "lf",
          "description": "Uses line feed."
        },
        {
          "const": "system",
          "description": "Uses the system standard (ex. crlf on Windows)."
        }
      ]
    },
    "includes": {
      "description": "Array of patterns (globs) to use to find files to format.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "excludes": {
      "description": "Array of patterns (globs) to exclude files or directories to format.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "plugins": {
      "description": "Array of plugin URLs to format files.",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "additionalProperties": {
    "description": "Plugin configuration.",
    "type": "object"
  }
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "default": {},
  "id": "https://json.schemastore.org/imgbotconfig.json",
  "properties": {
    "schedule": {
      "title": "Limits the PRs from Imgbot to once a day, once a week, or once a month respectively. The default behavior is to receive Imgbot PRs as images require optimization.",
      "type": "string",
      "enum": ["daily", "weekly", "monthly"],
      "default": ""
    },
    "ignoredFiles": {
      "title": "Limits the images optimized by Imgbot by essentially ignoring them",
      "type": "array",
      "items": {
        "title": "Accepts the syntax for searchPattern on Directory.EnumerateFiles()",
        "type": "string",
        "pattern": "^/?([^/]+/)*[^/]+/?$",
        "default": ""
      },
      "default": []
    },
    "aggressiveCompression": {
      "title": "Opt in to use lossy compression algorithms. The default behaviour without this setting is loss less compression.",
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "string",
          "enum": ["true", "false"]
        }
      ],
      "default": false
    },
    "compressWiki": {
      "title": "Opt in to also compress wiki repo. The default behaviour is opt out.",
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "string",
          "enum": ["true", "false"]
        }
      ],
      "default": false
    },
    "minKBReduced": {
      "title": "Can be used to limit the frequency of PRs Imgbot will open over time",
      "type": "number",
      "default": 10
    }
  },
  "title": "JSON Schema for configuration for ImgBot",
  "type": "object"
}

{
  "$id": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {
    "address": {
      "description": "A physical or virtual address, or a range of addresses, in an 'addressable region' (memory or a binary file).",
      "additionalProperties": false,
      "type": "object",
      "properties": {
        "absoluteAddress": {
          "description": "The address expressed as a byte offset from the start of the addressable region.",
          "type": "integer",
          "minimum": -1,
          "default": -1
        },
        "relativeAddress": {
          "description": "The address expressed as a byte offset from the absolute address of the top-most parent object.",
          "type": "integer"
        },
        "length": {
          "description": "The number of bytes in this range of addresses.",
          "type": "integer"
        },
        "kind": {
          "description": "An open-ended string that identifies the address kind. 'data', 'function', 'header','instruction', 'module', 'page', 'section', 'segment', 'stack', 'stackFrame', 'table' are well-known values.",
          "type": "string"
        },
        "name": {
          "description": "A name that is associated with the address, e.g., '.text'.",
          "type": "string"
        },
        "fullyQualifiedName": {
          "description": "A human-readable fully qualified name that is associated with the address.",
          "type": "string"
        },
        "offsetFromParent": {
          "description": "The byte offset of this address from the absolute or relative address of the parent object.",
          "type": "integer"
        },
        "index": {
          "description": "The index within run.addresses of the cached object for this address.",
          "type": "integer",
          "default": -1,
          "minimum": -1
        },
        "parentIndex": {
          "description": "The index within run.addresses of the parent object.",
          "type": "integer",
          "default": -1,
          "minimum": -1
        },
        "properties": {
          "description": "Key/value pairs that provide additional information about the address.",
          "$ref": "#/definitions/propertyBag"
        }
      }
    },
    "artifact": {
      "description": "A single artifact. In some cases, this artifact might be nested within another artifact.",
      "additionalProperties": false,
      "type": "object",
      "properties": {
        "description": {
          "description": "A short description of the artifact.",
          "$ref": "#/definitions/message"
        },
        "location": {
          "description": "The location of the artifact.",
          "$ref": "#/definitions/artifactLocation"
        },
        "parentIndex": {
          "description": "Identifies the index of the immediate parent of the artifact, if this artifact is nested.",
          "type": "integer",
          "default": -1,
          "minimum": -1
        },
        "offset": {
          "description": "The offset in bytes of the artifact within its containing artifact.",
          "type": "integer",
          "minimum": 0
        },
        "length": {
          "description": "The length of the artifact in bytes.",
          "type": "integer",
          "default": -1,
          "minimum": -1
        },
        "roles": {
          "description": "The role or roles played by the artifact in the analysis.",
          "type": "array",
          "minItems": 0,
          "uniqueItems": true,
          "default": [],
          "items": {
            "enum": [
              "analysisTarget",
              "attachment",
              "responseFile",
              "resultFile",
              "standardStream",
              "tracedFile",
              "unmodified",
              "modified",
              "added",
              "deleted",
              "renamed",
              "uncontrolled",
              "driver",
              "extension",
              "translation",
              "taxonomy",
              "policy",
              "referencedOnCommandLine",
              "memoryContents",
              "directory",
              "userSpecifiedConfiguration",
              "toolSpecifiedConfiguration",
              "debugOutputFile"
            ]
          }
        },
        "mimeType": {
          "description": "The MIME type (RFC 2045) of the artifact.",
          "type": "string",
          "pattern": "[^/]+/.+"
        },
        "contents": {
          "description": "The contents of the artifact.",
          "$ref": "#/definitions/artifactContent"
        },
        "encoding": {
          "description": "Specifies the encoding for an artifact object that refers to a text file.",
          "type": "string"
        },
        "sourceLanguage": {
          "description": "Specifies the source language for any artifact object that refers to a text file that contains source code.",
          "type": "string"
        },
        "hashes": {
          "description": "A dictionary, each of whose keys is the name of a hash function and each of whose values is the hashed value of the artifact produced by the specified hash function.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "lastModifiedTimeUtc": {
          "description": "The Coordinated Universal Time (UTC) date and time at which the artifact was most recently modified. See \"Date/time properties\" in the SARIF spec for the required format.",
          "type": "string",
          "format": "date-time"
        },
        "properties": {
          "description": "Key/value pairs that provide additional information about the artifact.",
          "$ref": "#/definitions/propertyBag"
        }
      }
    },
    "artifactChange": {
      "description": "A change to a single artifact.",
      "additionalProperties": false,
      "type": "object",
