        "timepicker": {
          "description": "timepicker metadata",
          "type": "object",
          "properties": {
            "collapse": {
              "description": "whether timepicker is collapsed or not",
              "type": "boolean"
            },
            "enable": {
              "description": "whether timepicker is enabled or not",
              "type": "boolean"
            },
            "notice": {
              "type": "boolean"
            },
            "now": {
              "type": "boolean"
            },
            "refresh_intervals": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "status": {
              "type": "string"
            },
            "type": {
              "type": "string"
            }
          }
        },
        "templating": {
          "description": "templating metadata",
          "type": "object",
          "properties": {
            "enable": {
              "description": "whether templating is enabled or not",
