    "strmprivacy.api.entities.v1.EncryptedData": {
      "type": "object",
      "properties": {
        "target": {
          "$ref": "#/definitions/strmprivacy.api.entities.v1.EncryptedData/definitions/target"
        }
      },
      "additionalProperties": {
        "title": "Unknown field"
      },
      "definitions": {
        "target": {
          "oneOf": [
            {
              "$ref": "#/definitions/strmprivacy.api.entities.v1.DataConnectorAndType"
            },
            {
              "type": "null"
            }
          ],
          "title": "strmprivacy.api.entities.v1.DataConnectorAndType target = 1;",
          "default": {

          }
        }
      }
    }
  },
  "title": "strmprivacy.api.entities.v1.DataConnector"
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "IBM Zapp Document",
  "description": "JSON schema for zapp.json and zapp.yaml files. Version 1.0.0 -- Licensed Materials - Property of IBM - (c) Copyright IBM Corporation 2022. All Rights Reserved.",
  "type": "object",
  "definitions": {
    "coreProperties": {
      "type": "object",
      "required": ["name"],
      "additionalProperties": false,
      "properties": {
        "name": {
          "description": "The name of the Z Project.",
          "type": "string",
          "maxLength": 214,
          "minLength": 1
        },
        "description": {
          "description": "This helps people understand your project as it would be used by tools.",
          "type": "string"
        },
        "version": {
          "description": "Version is a string and it must be parsable for managing dependencies.",
          "type": "string",
          "default": "1.0.0"
        },
        "groupId": {
          "description": "Defines a group name that is shared for each application part in case of applications composed of multiple parts. Allows to uniquely identify the parts by concatenating with the artifact id. For example a groupId `com.ibm.wazi` with an artifactId `service` would create the unique application identifier `com.ibm.wazi.service`.",
          "type": "string",
          "examples": ["com.ibm.wazi", "payments"]
        },
        "artifactId": {
          "description": "Define id of the application artifact. Use it in combination with a groupId for multi-part applications.",
          "type": "string",
          "default": "",
          "examples": ["sam"]
        },
        "parentId": {
          "description": "In case of a multi-part application defines the name of the parent application part. This zapp will inherit properties such as propertyGroups defined in the parent.",
          "type": "string",
          "default": "",
          "examples": ["com.ibm.wazi.parent"]
        },
        "keywords": {
          "description": "This helps people discover your project.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "homepage": {
          "description": "The url to the project homepage.",
          "type": "string",
          "oneOf": [
            {
              "format": "uri"
            },
            {
              "enum": ["."]
            }
          ]
        },
        "license": {
          "type": "string",
          "description": "You should specify a license for your package so that people know how they are permitted to use it and any restrictions you're placing on it."
        },
        "author": {
          "$ref": "#/definitions/person"
        },
        "contributors": {
          "description": "A list of people who contributed to this package.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/person"
          },
          "minItems": 1
        },
        "maintainers": {
          "description": "A list of people who maintain this package.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/person"
          },
          "minItems": 1
        },
        "propertyGroups": {
          "description": "A list properties defining path names for resolving dependencies.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/propertyGroupItem"
          },
          "minItems": 1
        },
        "profiles": {
          "description": "Profiles are additional groups of properties that should only should become valid under specific conditions such as running in a build job or as part of a debug session.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/profile"
          },
          "minItems": 1
        }
      }
    },
    "propertyGroupItem": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name"],
      "properties": {
        "name": {
          "type": "string",
          "description": "The name of the property group, which is used in hovers and error messages.",
          "examples": ["sample-local"]
        },
        "language": {
          "type": "string",
          "enum": ["cobol", "pl1", "hlasm", "rexx", "jcl"],
          "description": "Limits the property group to one specific language."
        },
        "compilerOptions": {
          "type": "string",
          "description": "Global compiler options separated by a comma that impact the parsing of the programs for the editor. Requires that you specify a language. If there are multiple Property Groups for a language with compiler option then they will be concatenated."
        },
        "libraries": {
          "type": "array",
          "description": "An array of potential library locations defining the search order for include files. Libraries with the name 'syslib' will be handled as default include locations. The list can contain many entries of the type 'local' or 'mvs'. It can contain items of the same type twice in case, for example, you want to search in remote locations first, then some local location, and if still not found more remote locations.",
          "items": {
            "$ref": "#/definitions/libraryItem"
          },
          "minItems": 1
        }
      }
    },
    "libraryItem": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "type", "locations"],
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the library. The default name should be `syslib` if using unamed libraries.",
          "default": "syslib",
          "examples": ["syslib", "currencylib"]
        },
        "type": {
          "type": "string",
          "enum": ["mvs", "local"],
          "description": "The type of the property group defining where dependencies should be located. Allowed values are 'local' for using a local workspace and 'mvs' for dependencies located in MVS Datasets.",
          "default": "local",
          "examples": ["local", "mvs"]
        },
        "locations": {
          "type": "array",
          "description": "An array of include file locations. For 'local' libraries values can be absolute and relative filename paths using GLOB patterns. For 'mvs' libraries value can be data set names. GLOB patterns for dat sets are currently not supported.",
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "examples": ["**/copybook", "USER1.SAMPLE.COBCOPY"]
        }
      }
    },
    "person": {
      "description": "A person who has been involved in creating or maintaining this package",
      "type": ["object", "string"],
      "required": ["name"],
      "properties": {
        "name": {
          "type": "string"
        },
        "url": {
          "type": "string",
          "format": "uri"
        },
        "email": {
          "type": "string",
          "format": "email"
        }
      }
    },
    "profile": {
      "type": "object",
      "description": "Profiles are additional groups of properties that should only should become valid under specific conditions such as running in a build job or as part of a debug session.",
      "additionalProperties": false,
      "required": ["name", "type"],
      "properties": {
        "name": {
          "type": "string",
          "description": "The name of the profile.",
          "examples": ["dbb-build"]
        },
        "type": {
          "type": "string",
          "enum": ["dbb", "rseapi", "debug"],
          "description": "The type of the profile.",
          "default": "dbb",
          "examples": ["dbb", "rseapi"]
        },
        "settings": {
          "description": "Settings objects specific to the type specified for the profile.",
          "type": "object"
        }
      },
      "anyOf": [
        {
          "required": ["name", "type", "settings"],
          "additionalProperties": false,
          "properties": {
            "name": { "type": "string" },
            "type": { "const": "dbb", "type": "string" },
            "settings": {
              "$ref": "#/definitions/dbbSettingsItem"
            }
          }
        },
        {
          "required": ["name", "type", "settings"],
          "additionalProperties": false,
          "properties": {
            "name": { "type": "string" },
            "type": { "const": "rseapi", "type": "string" },
            "settings": {
              "$ref": "#/definitions/rseapiSettingsItem"
            }
          }
        }
      ]
    },
    "dbbSettingsItem": {
      "type": "object",
      "additionalProperties": false,
      "required": ["application", "command"],
      "description": "DBB build script properties for running User Build on remote host.",
      "properties": {
        "application": {
          "type": "string",
          "description": "Defines the name of the application to build. Will be used to create a folder on USS to upload all files to."
        },
        "command": {
          "type": "string",
          "description": "Command that the build script is executed with such as the path to groovyz and it's parameters."
        },
        "buildScriptPath": {
          "type": "string",
          "description": "The full path of build script on the remote host that should be used with the command."
        },
        "buildScriptArgs": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "A list of strings that are the parameters for the build script. Check the documentation for built-in variables, such as the name of the program to build, that can be used here."
        },
        "additionalDependencies": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Lists of GLOB patterns that define the files that should be uploaded to USS for a build. Relative path names are interpreted relative to the location of the ZAPP file that is being used for the build, which is a ZAPP file in the same workspace as the program to be build."
        },
        "logFilePatterns": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Lists of GLOB patterns that define the files that should be downloaded from USS after the build. Relative path names are interpreted relative to the DBB log directory user setting. If not provided then all files of the user setting location will be downloaded."
        }
      }
    },
    "rseapiSettingsItem": {
      "type": "object",
      "additionalProperties": false,
      "description": "RSE API client settings for interactions with a z/OS remote host running an RSE API server.",
      "required": ["mappings", "default.encoding"],
      "properties": {
        "mappings": {
          "type": "array",
          "description": "A list of mapping objects that map local file extensions to transfer modes and encodings to MVS datasets that can be specified using wildcards.",
          "items": { "$ref": "#/definitions/rseapiSettingsItemMapping" }
        },
        "default.encoding": {
          "type": "string",
          "description": "The encoding to be used when no mapping can be found. If not provided then either the user or server default will be used."
        }
      }
    },
    "rseapiSettingsItemMapping": {
      "type": "object",
      "additionalProperties": false,
      "description": "One mapping that contains at least transfer and resource values.",
      "properties": {
        "extension": {
          "type": "string",
          "description": "A local file extension such as cbl or pl1."
        },
        "transfer": {
          "type": "string",
          "enum": ["text", "binary"],
          "description": "The transfer mode to be used. Can be 'text' or 'binary'."
        },
        "resource": {
          "type": "string",
          "description": "The data set name to be mapped to. Can use a wildcard such as '**CPY'."
        },
        "encoding": {
          "type": "string",
          "description": "The encoding to be used for text transfer. See the RSE API documentation for the values allowed."
        },
        "memberMappings": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "description": "One member mapping that contains at least transfer and resource values.",
            "properties": {
              "extension": {
                "type": "string",
                "description": "A local file extension such as cbl or pl1."
              },
              "transfer": {
                "type": "string",
                "enum": ["text", "binary"],
                "description": "The transfer mode to be used. Can be 'text' or 'binary'."
              },
              "encoding": {
                "type": "string",
                "description": "The encoding to be used for text transfer. See the RSE API documentation for the values allowed."
              },
              "resource": {
                "type": "string",
                "description": "The data set member name to be mapped to. Can use a wildcard such as '**CPY'."
              }
            }
          },
          "description": "A nested mappings array with resource mappings to members of the data sets that were mapped by the parent mapping."
        }
      }
    }
  },
  "anyOf": [
    {
      "$ref": "#/definitions/coreProperties"
    }
  ]
}

{
  "$id": "https://json.schemastore.org/cloud-sdk-pipeline-config-schema.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "dockerImage": {
      "description": "The image used in the step or stage.",
      "type": "string"
    },
    "org": {
      "description": "Cloud Foundry organization.",
      "type": "string"
    },
    "space": {
      "description": "Cloud Foundry space.",
      "type": "string"
    },
    "appName": {
      "description": "Name of the application.",
      "type": "string"
    },
    "manifest": {
      "description": "Manifest file that needs to be used.",
      "type": "string"
    },
    "credentialsId": {
      "description": "ID to the credentials that will be used.",
      "type": "string"
    },
    "apiEndpoint": {
      "description": "URL to the Cloud Foundry endpoint.",
      "type": "string",
      "default": "https://api.cf.eu10.hana.ondemand.com"
    },
    "mtaExtensionDescriptor": {
      "description": "(Only for MTA-projects) Path to the mta extension description file. For more information on how to use those extension files please visit the SAP HANA Developer Guide.",
      "type": "string"
    },
    "mtaExtensionCredentials": {
      "description": "(Only for MTA-projects) Map of credentials that need to be replaced in the mtaExtensionDescriptor. This map needs to be created as value-to-be-replaced:id-of-a-credential-in-jenkins",
      "type": "string"
    },
    "host": {
      "description": "Host of the region you want to deploy to, see Regions.",
      "type": "string"
    },
    "account": {
      "description": "Identifier of the subaccount.",
      "type": "string"
    },
    "application": {
      "description": "Name of the application in your account.",
      "type": "string"
    },
    "environment": {
      "description": "Map of environment variables in the form of KEY: VALUE.",
      "type": "object"
    },
    "vmArguments": {
      "description": "String of VM arguments passed to the JVM.",
      "type": "string"
    },
    "size": {
      "description": "Size of the JVM, e.g. lite, pro, prem, prem-plus.",
      "type": "string",
      "default": "lite"
    },
    "runtime": {
      "description": "Name of the runtime: neo-java-web, neо-javaee6-wp, neо-javaee7-wp. See the runtime for more information.",
      "type": "string"
    },
    "runtimeVersion": {
      "description": "Version of the runtime. See runtime-version for more information.",
      "type": "string"
    },
    "neoTargets": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "host": {
            "$ref": "#/definitions/host"
          },
          "account": {
            "$ref": "#/definitions/account"
          },
          "application": {
            "$ref": "#/definitions/application"
          },
          "credentialsId": {
            "$ref": "#/definitions/credentialsId"
          },
          "environment": {
            "$ref": "#/definitions/environment"
          },
          "vmArguments": {
            "$ref": "#/definitions/vmArguments"
          },
          "size": {
            "$ref": "#/definitions/size"
          },
          "runtime": {
            "$ref": "#/definitions/runtime"
          },
          "runtimeVersion": {
            "$ref": "#/definitions/runtimeVersion"
          }
        },
        "required": [
          "host",
          "account",
          "application",
          "runtime",
          "runtimeVersion"
        ],
        "additionalProperties": false
      }
    },
    "appUrls": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "url": {
            "description": "The URLs under which the app is available after deployment. Each appUrl can be a string with the URL or a map containing a property url and a property credentialId.",
            "type": "string"
          },
          "credentialId": {
            "description": "ID to the credentials that will be used to connect to the SAP Cloudplatform account.",
            "type": "string"
          },
          "parameters": {
            "description": "Additional parameters can be passed for each end-to-end test deployment by specifying optional parameters for an application URL. These parameters are appended to the npm command during execution. These parameters must be a list of strings, where each string corresponds to one element of the parameters. For example, if the parameter `--tag scenario1` should be passed to the test, specify parameters: ['--tag', 'scenario1'].",
            "type": "array"
          }
        },
        "required": ["url"],
        "additionalProperties": false
      }
    },
    "cfTargets": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "org": {
            "$ref": "#/definitions/org"
          },
          "space": {
            "$ref": "#/definitions/space"
          },
          "appName": {
            "$ref": "#/definitions/appName"
          },
          "manifest": {
            "$ref": "#/definitions/manifest"
          },
          "credentialsId": {
            "$ref": "#/definitions/credentialsId"
          },
          "apiEndpoint": {
            "$ref": "#/definitions/apiEndpoint"
          },
          "mtaExtensionDescriptor": {
            "$ref": "#/definitions/mtaExtensionDescriptor"
          },
          "mtaExtensionCredentials": {
            "$ref": "#/definitions/mtaExtensionCredentials"
          }
        },
        "additionalProperties": false
      }
    },
    "cloudFoundry": {
      "description": "A map specifying the Cloud Foundry specific parameters.",
      "type": "object",
      "properties": {
        "org": {
          "$ref": "#/definitions/org"
        },
        "space": {
          "$ref": "#/definitions/space"
        },
        "appName": {
          "$ref": "#/definitions/appName"
        },
        "manifest": {
          "$ref": "#/definitions/manifest"
        },
        "credentialsId": {
          "$ref": "#/definitions/credentialsId"
        },
        "apiEndpoint": {
          "$ref": "#/definitions/apiEndpoint"
        },
        "mtaExtensionDescriptor": {
          "$ref": "#/definitions/mtaExtensionDescriptor"
        },
        "mtaExtensionCredentials": {
          "$ref": "#/definitions/mtaExtensionCredentials"
        }
      },
      "additionalProperties": false
    }
  },
  "description": "The configuration file of the SAP Cloud SDK Continuous Delivery Toolkit. For more information please visit https://github.com/SAP/cloud-s4-sdk-pipeline",
  "postActions": {
    "type": "object",
    "properties": {
      "sendNotification": {
        "description": "The sendNotification post-build action can be used to send notifications to project members in case of an unsuccessful build outcome or if the build goes back to normal. By default, an email is sent to the list of users who committed a change since the last non-broken build. Additionally, a set of recipients can be defined that should always receive notifications.",
        "type": ["object", "null"],
        "properties": {
          "enabled": {
            "description": "If set to true, notifications will be sent.",
            "type": "boolean",
            "default": false
          },
          "skipFeatureBranches": {
            "description": "If set to true, notifications will only be sent for the productive branch as defined in the general configuration section.",
            "type": "boolean",
            "default": false
          },
          "recipients": {
            "description": "List of email addresses that should be notified in addition to the standard recipients.",
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        }
      }
    }
  },
  "properties": {
    "customDefaults": {
      "description": "List of paths or URLs to YAML files with custom defaults to consider. These defaults override built-in defaults, and can be shared across multiple projects. Project configuration takes precedence.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "general": {
      "description": "The general configuration of the pipeline",
      "type": ["object", "null"],
      "properties": {
        "productiveBranch": {
          "description": "The name of your default branch. This branch will be used for deploying your application. Other branches will skip deployment.",
          "type": "string",
          "default": "master"
        },
        "projectName": {
          "description": "Name of the project. Will be used as identifier e.g. when creating a hdi container or executing code scans.",
          "type": "string"
        },
        "globalExtensionsRepository": {
          "description": "Git url of the repository containing the extensions.",
          "type": "string"
        },
        "globalExtensionsVersion": {
          "description": "Version of the extensions which should be used, e.g. the tag name",
          "type": "string"
        },
        "globalExtensionsRepositoryCredentialsId": {
          "description": "Credentials required to clone the repository",
          "type": "string"
        },
        "collectTelemetryData": {
          "description": "No personal data is collected. For details, consult the analytics documentation.",
          "type": "boolean",
          "default": true
        },
        "unsafeMode": {
          "description": "Enable unsafe mode to skip checking environment variables for insecure elements. Only use this for demo purposes, never for productive usage.",
          "type": "boolean",
          "default": false
        },
        "features": {
          "description": "Allows enabling or disable certain optional features.",
          "type": "object",
          "properties": {
            "parallelTestExecution": {
              "description": "Run E2E Tests in parallel. This feature is disabled by default because it is not supported in Blue Ocean. If this feature is enabled, we suggest not using the Blue Ocean interface and rely on the classic UI instead.",
              "type": "string",
              "enum": ["on", "off"],
              "default": "off"
            }
          },
          "additionalProperties": true
        },
        "jenkinsKubernetes": {
          "description": "If the Jenkins is running on a kubernetes cluster as a pod, we can use the dynamic scaling feature in the pipeline. In order to enable this, an environment variable ON_K8S has to be set to true on the jenkins.",
          "type": "object",
          "properties": {
            "jnlpAgent": {
              "description": "Docker image for jnlp agent to be used.",
              "type": "string",
              "default": "jenkins/jnlp-slave:latest"
            }
          },
          "additionalProperties": true
        }
      },
      "additionalProperties": false
    },
    "stages": {
      "description": "Configuration, which will modify the behaviour of stages in the SAP Cloud SDK Pipeline.",
      "type": ["object", "null"],
      "properties": {
        "backendIntegrationTests": {
          "type": "object",
          "properties": {
            "retry": {
              "description": "The number of times that integration tests will retry before aborting the build. Note: This will consume more time for the jenkins build.",
              "type": "integer",
              "default": 1
            },
            "forkCount": {
              "description": "The number of JVM processes that are spawned to run the tests in parallel in case of using a maven based project structure. For more details visit the surefire documentation.",
              "type": "string",
              "default": "1C"
            },
            "credentials": {
              "description": "The list of system credentials to be injected during integration tests. The following example will provide the username and password for the systems with the aliases ERP and SFSF. For this, it will use the Jenkins credentials entries erp-credentials and successfactors-credentials. You have to ensure that corresponding credential entries exist in your Jenkins configuration.",
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "alias": {
                    "type": "string"
                  },
                  "credentialId": {
                    "type": "string"
                  }
                },
                "required": ["alias", "credentialId"],
                "additionalProperties": false
              }
            },
            "sidecarImage": {
              "description": "Name of the Docker image that should be used.",
              "type": "string"
            },
            "sidecarName": {
              "description": "On Docker: Name of the container in the local network. On Kubernetes: Name of the container.",
              "type": "string"
            },
            "sidecarReadyCommand": {
              "description": "Command executed inside the container, which returns exit code 0 when the container is ready to be used.",
              "type": "string"
            },
            "sidecarEnvVars": {
              "description": "Environment variables to set in the container.",
              "type": "object"
            }
          },
          "additionalProperties": false
        },
        "frontEndIntegrationTests": {
          "type": "object",
          "properties": {
            "dockerImage": {
              "$ref": "#/definitions/dockerImage"
            }
          },
          "additionalProperties": false
        },
        "frontEndUnitTests": {
          "type": "object",
          "properties": {
            "dockerImage": {
              "$ref": "#/definitions/dockerImage"
            }
          },
          "additionalProperties": false
        },
        "endToEndTests": {
          "type": "object",
          "properties": {
            "enableZeroDowntimeDeployment": {
              "description": "It is possible to activate zero downtime deployment in end-to-end tests with the option enableZeroDowntimeDeployment. This will lead to a blue-green-deployment on SCP Cloud Foundry respectively to a rolling update on SCP Neo. By default, this feature is turned off.",
              "type": "boolean"
            },
            "onlyRunInProductiveBranch": {
